// GERADO por scripts/gen-migrations.mjs — não editar à mão.
export const MIGRATIONS: [string, string][] = [
  ["0001_base.sql", "-- 0001 — Base: extensões, papel da aplicação, contexto de pedido, contas, organizações, planos, auditoria.\n-- Reversão: ver 0001_base.down.sql (apaga tudo o que esta migração cria).\n\ncreate extension if not exists postgis;\ncreate extension if not exists pg_trgm;\ncreate extension if not exists btree_gist;\ncreate extension if not exists pgcrypto;\ncreate extension if not exists citext;\n\n-- Papel usado pela API (Vercel Functions). NÃO é dono das tabelas → o RLS aplica-se sempre.\n-- A palavra-passe NUNCA fica no repositório: é definida no deploy (ALTER ROLE ... LOGIN PASSWORD).\ndo $$ begin\n  if not exists (select 1 from pg_roles where rolname = 'app_api') then\n    create role app_api nologin;\n  end if;\nend $$;\ngrant usage on schema public to app_api;\n\n-- ── Contexto do pedido (definido pela API com set_config(..., true) dentro da transação) ──\ncreate or replace function app_user_id() returns uuid language sql stable as\n$$ select nullif(current_setting('app.user_id', true), '')::uuid $$;\ncreate or replace function app_driver_id() returns uuid language sql stable as\n$$ select nullif(current_setting('app.driver_id', true), '')::uuid $$;\n\ncreate or replace function set_updated_at() returns trigger language plpgsql as\n$$ begin new.updated_at := now(); return new; end $$;\n\n-- ── Contas ──\ncreate table app_users (\n  id uuid primary key default gen_random_uuid(),\n  email citext not null unique check (email ~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$'),\n  password_hash text not null,\n  full_name text not null check (length(full_name) between 2 and 120),\n  phone text check (phone ~ '^\\+[1-9][0-9]{7,14}$'),\n  is_platform_admin boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger t_app_users_upd before update on app_users for each row execute function set_updated_at();\n\ncreate table auth_sessions (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references app_users(id) on delete cascade,\n  token_hash text not null unique,\n  active_org_id uuid,\n  user_agent text,\n  expires_at timestamptz not null,\n  revoked_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index on auth_sessions (user_id);\n\ncreate table password_resets (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references app_users(id) on delete cascade,\n  token_hash text not null unique,\n  expires_at timestamptz not null,\n  used_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\n-- ── Planos e organizações ──\ncreate table plans (\n  id uuid primary key default gen_random_uuid(),\n  code text not null unique,\n  name text not null,\n  limits jsonb not null default '{}'::jsonb,\n  price numeric(14,2) not null default 0 check (price >= 0),\n  currency char(3) not null default 'MZN',\n  is_public boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger t_plans_upd before update on plans for each row execute function set_updated_at();\n\ninsert into plans (code, name, limits, price) values\n ('trial', 'Experimental', '{\"max_vehicles\":5,\"max_devices\":5,\"max_members\":3,\"max_active_shares\":20,\"retention_days\":30}', 0),\n ('basico', 'Básico', '{\"max_vehicles\":20,\"max_devices\":20,\"max_members\":10,\"max_active_shares\":200,\"retention_days\":30}', 0),\n ('frota', 'Frota', '{\"max_vehicles\":200,\"max_devices\":200,\"max_members\":50,\"max_active_shares\":5000,\"retention_days\":90}', 0);\n\ncreate type org_role as enum ('owner', 'admin', 'dispatcher', 'viewer');\n\ncreate table organizations (\n  id uuid primary key default gen_random_uuid(),\n  name text not null check (length(name) between 2 and 120),\n  phone text check (phone ~ '^\\+[1-9][0-9]{7,14}$'),\n  province text,\n  timezone text not null default 'Africa/Maputo',\n  default_currency char(3) not null default 'MZN',\n  settings jsonb not null default '{\n     \"freshness_current_s\":120, \"freshness_stale_s\":900, \"late_tolerance_min\":30,\n     \"doc_alert_days\":[30,15,7], \"gps_interval_moving_s\":15, \"gps_interval_stopped_s\":120,\n     \"deviation_corridor_m\":500, \"deviation_points\":3, \"deviation_min_minutes\":3,\n     \"abnormal_stop_minutes\":30, \"voice_min_importance\":3}'::jsonb,\n  public_name text,\n  logo_file_id uuid,\n  deleted_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger t_org_upd before update on organizations for each row execute function set_updated_at();\n\ncreate table organization_members (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  user_id uuid not null references app_users(id) on delete cascade,\n  role org_role not null,\n  invited_by uuid references app_users(id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, user_id)\n);\ncreate index on organization_members (user_id);\ncreate trigger t_mem_upd before update on organization_members for each row execute function set_updated_at();\n\ncreate table organization_invites (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  email citext not null,\n  role org_role not null check (role <> 'owner'),\n  token_hash text not null unique,\n  invited_by uuid references app_users(id) on delete set null,\n  expires_at timestamptz not null,\n  accepted_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate unique index on organization_invites (organization_id, email) where accepted_at is null;\ncreate trigger t_inv_upd before update on organization_invites for each row execute function set_updated_at();\n\ncreate table subscriptions (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  plan_id uuid not null references plans(id),\n  status text not null default 'trial' check (status in ('trial','active','past_due','canceled')),\n  period_start timestamptz not null default now(),\n  period_end timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate unique index on subscriptions (organization_id) where status <> 'canceled';\ncreate trigger t_sub_upd before update on subscriptions for each row execute function set_updated_at();\n\ncreate table usage_counters (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  period date not null,\n  positions_ingested bigint not null default 0,\n  route_requests bigint not null default 0,\n  public_views bigint not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, period)\n);\n\n-- Acesso de suporte da plataforma: temporário e auditado (SPEC §2).\ncreate table support_grants (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  user_id uuid not null references app_users(id) on delete cascade,\n  reason text not null check (length(reason) >= 5),\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table audit_logs (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid references organizations(id) on delete cascade,\n  actor_type text not null check (actor_type in ('member','driver','system','platform','anonymous')),\n  actor_id uuid,\n  action text not null,\n  entity text not null,\n  entity_id uuid,\n  before jsonb,\n  after jsonb,\n  ip_hash text,\n  at timestamptz not null default now(),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on audit_logs (organization_id, at desc);\n\n-- ── Funções de permissão (SECURITY DEFINER para não haver recursão de RLS) ──\ncreate or replace function is_member(org uuid, roles org_role[] default null) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select exists (\n    select 1 from organization_members m\n    where m.organization_id = org and m.user_id = app_user_id()\n      and (roles is null or m.role = any(roles))\n  ) or (\n    -- suporte da plataforma: só leitura (roles is null) e dentro da validade\n    roles is null and exists (\n      select 1 from support_grants g join app_users u on u.id = g.user_id\n      where g.organization_id = org and g.user_id = app_user_id()\n        and u.is_platform_admin and g.expires_at > now()\n    )\n  )\n$$;\n\ncreate or replace function can_write(org uuid) returns boolean language sql stable as\n$$ select is_member(org, array['owner','admin','dispatcher']::org_role[]) $$;\ncreate or replace function can_admin(org uuid) returns boolean language sql stable as\n$$ select is_member(org, array['owner','admin']::org_role[]) $$;\n\ncreate or replace function is_platform_admin() returns boolean\nlanguage sql stable security definer set search_path = public as\n$$ select coalesce((select is_platform_admin from app_users where id = app_user_id()), false) $$;\n\n-- Tem de existir sempre pelo menos um owner.\ncreate or replace function guard_last_owner() returns trigger language plpgsql security definer set search_path = public as $$\ndeclare remaining int;\nbegin\n  if (tg_op = 'DELETE' and old.role = 'owner') or (tg_op = 'UPDATE' and old.role = 'owner' and new.role <> 'owner') then\n    select count(*) into remaining from organization_members\n      where organization_id = old.organization_id and role = 'owner' and id <> old.id;\n    if remaining = 0 and exists (select 1 from organizations where id = old.organization_id) then\n      raise exception 'ultimo_owner' using errcode = 'P0001';\n    end if;\n  end if;\n  return coalesce(new, old);\nend $$;\ncreate trigger t_mem_last_owner before update or delete on organization_members\n  for each row execute function guard_last_owner();\n\n-- ── Funções de autenticação (chamadas pela API antes de haver contexto de utilizador) ──\ncreate or replace function auth_register(p_email text, p_password_hash text, p_full_name text,\n  p_org_name text, p_phone text, p_province text)\nreturns table (user_id uuid, organization_id uuid)\nlanguage plpgsql security definer set search_path = public as $$\ndeclare u uuid; o uuid; trial uuid;\nbegin\n  insert into app_users (email, password_hash, full_name, phone)\n    values (p_email, p_password_hash, p_full_name, nullif(p_phone, '')) returning id into u;\n  insert into organizations (name, phone, province) values (p_org_name, nullif(p_phone, ''), nullif(p_province, ''))\n    returning id into o;\n  insert into organization_members (organization_id, user_id, role) values (o, u, 'owner');\n  select id into trial from plans where code = 'trial';\n  insert into subscriptions (organization_id, plan_id, status, period_end) values (o, trial, 'trial', now() + interval '60 days');\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (o, 'member', u, 'organizacao.criar', 'organizations', o);\n  return query select u, o;\nend $$;\n\ncreate or replace function auth_user_by_email(p_email text)\nreturns table (id uuid, password_hash text, full_name text)\nlanguage sql stable security definer set search_path = public as\n$$ select id, password_hash, full_name from app_users where email = p_email $$;\n\ncreate or replace function auth_session_create(p_user uuid, p_token_hash text, p_ua text, p_ttl_hours int)\nreturns uuid language plpgsql security definer set search_path = public as $$\ndeclare s uuid; org uuid;\nbegin\n  select organization_id into org from organization_members where user_id = p_user order by created_at limit 1;\n  insert into auth_sessions (user_id, token_hash, user_agent, expires_at, active_org_id)\n    values (p_user, p_token_hash, left(p_ua, 300), now() + make_interval(hours => p_ttl_hours), org)\n    returning id into s;\n  return s;\nend $$;\n\ncreate or replace function auth_session_resolve(p_token_hash text)\nreturns table (session_id uuid, user_id uuid, active_org_id uuid, is_platform_admin boolean, full_name text, email text)\nlanguage sql stable security definer set search_path = public as $$\n  select s.id, s.user_id, s.active_org_id, u.is_platform_admin, u.full_name, u.email::text\n  from auth_sessions s join app_users u on u.id = s.user_id\n  where s.token_hash = p_token_hash and s.revoked_at is null and s.expires_at > now()\n$$;\n\ncreate or replace function auth_session_revoke(p_token_hash text) returns void\nlanguage sql security definer set search_path = public as\n$$ update auth_sessions set revoked_at = now() where token_hash = p_token_hash and revoked_at is null $$;\n\ncreate or replace function auth_session_switch_org(p_token_hash text, p_org uuid) returns boolean\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  update auth_sessions s set active_org_id = p_org\n   where s.token_hash = p_token_hash and s.revoked_at is null\n     and exists (select 1 from organization_members m where m.user_id = s.user_id and m.organization_id = p_org);\n  return found;\nend $$;\n\ncreate or replace function auth_password_reset_create(p_email text, p_token_hash text) returns boolean\nlanguage plpgsql security definer set search_path = public as $$\ndeclare u uuid;\nbegin\n  select id into u from app_users where email = p_email;\n  if u is null then return false; end if;\n  insert into password_resets (user_id, token_hash, expires_at) values (u, p_token_hash, now() + interval '1 hour');\n  return true;\nend $$;\n\ncreate or replace function auth_password_reset_use(p_token_hash text, p_new_hash text) returns boolean\nlanguage plpgsql security definer set search_path = public as $$\ndeclare r password_resets;\nbegin\n  select * into r from password_resets where token_hash = p_token_hash and used_at is null and expires_at > now() for update;\n  if r.id is null then return false; end if;\n  update password_resets set used_at = now() where id = r.id;\n  update app_users set password_hash = p_new_hash where id = r.user_id;\n  update auth_sessions set revoked_at = now() where user_id = r.user_id and revoked_at is null;\n  return true;\nend $$;\n\ncreate or replace function auth_invite_accept(p_token_hash text, p_user uuid) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare i organization_invites; em citext;\nbegin\n  select email into em from app_users where id = p_user;\n  select * into i from organization_invites where token_hash = p_token_hash and accepted_at is null and expires_at > now() for update;\n  if i.id is null or i.email <> em then return null; end if;\n  insert into organization_members (organization_id, user_id, role, invited_by)\n    values (i.organization_id, p_user, i.role, i.invited_by) on conflict (organization_id, user_id) do nothing;\n  update organization_invites set accepted_at = now() where id = i.id;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (i.organization_id, 'member', p_user, 'membro.aceitar_convite', 'organization_members', p_user);\n  return i.organization_id;\nend $$;\n\n-- ── Limites do plano (verificados na BD, SPEC §6.14) ──\ncreate or replace function plan_limit(org uuid, key text) returns int\nlanguage sql stable security definer set search_path = public as $$\n  select (p.limits ->> key)::int from subscriptions s join plans p on p.id = s.plan_id\n  where s.organization_id = org and s.status <> 'canceled' limit 1\n$$;\n"],
  ["0002_frota.sql", "-- 0002 — Frota: ficheiros, camiões, motoristas, documentos, acesso do motorista, dispositivos GPS.\n-- Reversão: 0002_frota.down.sql.\n\n-- Ficheiros privados (fotografias, documentos, recibos, assinaturas).\n-- Guardados na própria BD (bytea, ≤ 2 MB depois de comprimidos no navegador) — ver ADR-017.\ncreate table files (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  kind text not null check (kind in ('vehicle_photo','driver_photo','document','receipt','delivery_photo','signature','incident_photo','logo')),\n  content_type text not null check (content_type in ('image/jpeg','image/png','image/webp','application/pdf')),\n  size_bytes int not null check (size_bytes between 1 and 2097152),\n  data bytea not null,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on files (organization_id);\n\ncreate table vehicles (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  plate text not null check (length(trim(plate)) between 3 and 15),\n  plate_normalized text generated always as (upper(regexp_replace(trim(plate), '\\s+', ' ', 'g'))) stored,\n  make text, model text,\n  year int check (year between 1950 and 2100),\n  body_type text not null default 'rigido' check (body_type in ('rigido','trator','basculante','cisterna','frigorifico','outro')),\n  capacity_t numeric(6,2) check (capacity_t > 0),\n  gross_weight_t numeric(6,2) check (gross_weight_t > 0),\n  length_m numeric(5,2) check (length_m > 0),\n  width_m numeric(4,2) check (width_m > 0),\n  height_m numeric(4,2) check (height_m > 0),\n  axles int check (axles between 2 and 12),\n  odometer_km numeric(10,1) check (odometer_km >= 0),\n  photo_file_id uuid references files(id) on delete set null,\n  admin_status text not null default 'ativo' check (admin_status in ('ativo','em_manutencao','inativo')),\n  gps_source_priority text not null default 'device' check (gps_source_priority in ('device','phone')),\n  notes text,\n  deleted_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate unique index vehicles_plate_uq on vehicles (organization_id, plate_normalized) where deleted_at is null;\ncreate trigger t_veh_upd before update on vehicles for each row execute function set_updated_at();\n\ncreate table drivers (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  full_name text not null check (length(full_name) between 2 and 120),\n  phone text not null check (phone ~ '^\\+[1-9][0-9]{7,14}$'),\n  license_number text,\n  license_category text,\n  photo_file_id uuid references files(id) on delete set null,\n  status text not null default 'ativo' check (status in ('ativo','inativo')),\n  deleted_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate unique index drivers_phone_uq on drivers (organization_id, phone) where deleted_at is null;\ncreate trigger t_drv_upd before update on drivers for each row execute function set_updated_at();\n\ncreate table documents (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  vehicle_id uuid references vehicles(id) on delete cascade,\n  driver_id uuid references drivers(id) on delete cascade,\n  doc_type text not null check (doc_type in ('carta_conducao','seguro','inspecao','licenca_transporte','manifesto','livrete','outro')),\n  number text,\n  issued_on date,\n  expires_on date,\n  file_id uuid references files(id) on delete set null,\n  notes text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  check (num_nonnulls(vehicle_id, driver_id) = 1),\n  check (expires_on is null or issued_on is null or expires_on >= issued_on)\n);\ncreate index on documents (organization_id, expires_on);\ncreate trigger t_doc_upd before update on documents for each row execute function set_updated_at();\n\n-- Acesso do motorista à PWA: link (token) + PIN. Só hashes (ADR-008).\ncreate table driver_access (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  driver_id uuid not null references drivers(id) on delete cascade,\n  token_hash text not null unique,\n  pin_hash text not null,\n  failed_attempts int not null default 0,\n  locked_until timestamptz,\n  last_used_at timestamptz,\n  revoked_at timestamptz,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate unique index driver_access_one_active on driver_access (driver_id) where revoked_at is null;\ncreate trigger t_dacc_upd before update on driver_access for each row execute function set_updated_at();\n\ncreate table driver_sessions (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  driver_id uuid not null references drivers(id) on delete cascade,\n  access_id uuid not null references driver_access(id) on delete cascade,\n  token_hash text not null unique,\n  expires_at timestamptz not null,\n  revoked_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table driver_consents (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  driver_id uuid not null references drivers(id) on delete cascade,\n  consent_version text not null,\n  accepted_at timestamptz not null default now(),\n  user_agent text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (driver_id, consent_version)\n);\n\n-- Dispositivos GPS físicos e histórico de associação (correção 12).\ncreate table gps_devices (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  imei text not null unique check (imei ~ '^[0-9]{10,20}$'),\n  protocol text,\n  model text,\n  sim_phone text check (sim_phone is null or sim_phone ~ '^\\+[1-9][0-9]{7,14}$'),\n  traccar_device_id bigint,\n  last_contact_at timestamptz,\n  status text not null default 'ativo' check (status in ('ativo','inativo')),\n  deleted_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger t_dev_upd before update on gps_devices for each row execute function set_updated_at();\n\ncreate table device_assignments (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  device_id uuid not null references gps_devices(id) on delete cascade,\n  vehicle_id uuid not null references vehicles(id) on delete cascade,\n  valid_from timestamptz not null default now(),\n  valid_to timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  check (valid_to is null or valid_to > valid_from),\n  exclude using gist (device_id with =, tstzrange(valid_from, coalesce(valid_to, 'infinity')) with &&),\n  exclude using gist (vehicle_id with =, tstzrange(valid_from, coalesce(valid_to, 'infinity')) with &&)\n);\n\n-- Chaves de ingestão (Traccar / simulador), por organização. Só o hash.\ncreate table ingest_keys (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  name text not null,\n  key_hash text not null unique,\n  scope text not null check (scope in ('traccar','simulator')),\n  last_used_at timestamptz,\n  revoked_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\n-- Limites do plano aplicados na BD.\ncreate or replace function enforce_plan_limit() returns trigger language plpgsql security definer set search_path = public as $$\ndeclare lim int; cnt int; key text := tg_argv[0];\nbegin\n  lim := plan_limit(new.organization_id, key);\n  if lim is null then return new; end if;\n  execute format('select count(*) from %I where organization_id = $1 and %s', tg_table_name,\n    case tg_table_name when 'vehicles' then 'deleted_at is null' when 'gps_devices' then 'deleted_at is null' else 'true' end)\n    into cnt using new.organization_id;\n  if cnt >= lim then\n    raise exception 'limite_plano:%', key using errcode = 'P0001';\n  end if;\n  return new;\nend $$;\ncreate trigger t_veh_limit before insert on vehicles for each row execute function enforce_plan_limit('max_vehicles');\ncreate trigger t_dev_limit before insert on gps_devices for each row execute function enforce_plan_limit('max_devices');\ncreate trigger t_mem_limit before insert on organization_members for each row execute function enforce_plan_limit('max_members');\n\n-- Funções de sessão do motorista (antes de haver contexto).\ncreate or replace function driver_access_lookup(p_token_hash text)\nreturns table (access_id uuid, driver_id uuid, organization_id uuid, pin_hash text, locked_until timestamptz, revoked boolean, driver_active boolean)\nlanguage sql stable security definer set search_path = public as $$\n  select a.id, a.driver_id, a.organization_id, a.pin_hash, a.locked_until, a.revoked_at is not null,\n         d.status = 'ativo' and d.deleted_at is null\n  from driver_access a join drivers d on d.id = a.driver_id where a.token_hash = p_token_hash\n$$;\n\ncreate or replace function driver_access_attempt(p_access uuid, p_ok boolean) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if p_ok then\n    update driver_access set failed_attempts = 0, locked_until = null, last_used_at = now() where id = p_access;\n  else\n    update driver_access set failed_attempts = failed_attempts + 1,\n      locked_until = case when failed_attempts + 1 >= 5 then now() + interval '15 minutes' else locked_until end\n    where id = p_access;\n  end if;\nend $$;\n\ncreate or replace function driver_session_create(p_access uuid, p_token_hash text, p_ttl_hours int) returns void\nlanguage sql security definer set search_path = public as $$\n  insert into driver_sessions (organization_id, driver_id, access_id, token_hash, expires_at)\n  select organization_id, driver_id, id, p_token_hash, now() + make_interval(hours => p_ttl_hours)\n  from driver_access where id = p_access and revoked_at is null\n$$;\n\ncreate or replace function driver_session_resolve(p_token_hash text)\nreturns table (driver_id uuid, organization_id uuid, full_name text, revoked_at timestamptz)\nlanguage sql stable security definer set search_path = public as $$\n  select s.driver_id, s.organization_id, d.full_name, coalesce(s.revoked_at, a.revoked_at)\n  from driver_sessions s join driver_access a on a.id = s.access_id join drivers d on d.id = s.driver_id\n  where s.token_hash = p_token_hash and s.expires_at > now()\n$$;\n\ncreate or replace function ingest_key_resolve(p_key_hash text)\nreturns table (key_id uuid, organization_id uuid, scope text)\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  return query update ingest_keys k set last_used_at = now()\n    where k.key_hash = p_key_hash and k.revoked_at is null returning k.id, k.organization_id, k.scope;\nend $$;\n"],
  ["0003_viagens.sql", "-- 0003 — Viagens: viagens, paragens, eventos, máquina de estados, ocorrências, comprovativos.\n-- Reversão: 0003_viagens.down.sql.\n\ncreate type trip_status as enum ('planeada','aguardando_partida','em_viagem','pausada','concluida','cancelada');\n\n-- Código curto FT-XXXX-XXXX: Crockford Base32 sem 0, 1 (e sem I, L, O, U) → 30 símbolos, 8 caracteres ≈ 39 bits.\ncreate or replace function gen_ft_code() returns text language plpgsql volatile as $$\ndeclare alphabet constant text := '23456789ABCDEFGHJKMNPQRSTVWXYZ'; b bytea; s text := ''; i int;\nbegin\n  b := gen_random_bytes(8);\n  for i in 0..7 loop\n    -- rejeição simples para evitar viés: bytes ≥ 240 são novamente sorteados\n    while get_byte(b, i) >= 240 loop b := set_byte(b, i, get_byte(gen_random_bytes(1), 0)); end loop;\n    s := s || substr(alphabet, (get_byte(b, i) % 30) + 1, 1);\n  end loop;\n  return 'FT-' || substr(s, 1, 4) || '-' || substr(s, 5, 4);\nend $$;\n\ncreate table places (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid references organizations(id) on delete cascade, -- null = público (importado)\n  name text not null,\n  name_variants text[] not null default '{}',\n  kind text not null check (kind in ('city','town','village','locality','bridge','toll','checkpoint','weighbridge','fuel','border',\n                                     'warehouse','customer','depot','workshop','other')),\n  importance smallint not null default 1 check (importance between 1 and 5),\n  province_id uuid,\n  district_id uuid,\n  geom geography(Point, 4326) not null,\n  osm_id text,\n  dataset_id uuid,\n  deleted_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  check (organization_id is null or osm_id is null)\n);\ncreate index places_geom_gix on places using gist (geom);\ncreate index places_name_trgm on places using gin (name gin_trgm_ops);\ncreate unique index places_osm_uq on places (osm_id) where osm_id is not null;\ncreate trigger t_pl_upd before update on places for each row execute function set_updated_at();\n\ncreate table trips (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  code text not null unique default gen_ft_code(),\n  vehicle_id uuid references vehicles(id) on delete restrict,\n  driver_id uuid references drivers(id) on delete restrict,\n  origin_place_id uuid not null references places(id),\n  destination_place_id uuid not null references places(id),\n  status trip_status not null default 'planeada',\n  planned_departure timestamptz,\n  planned_arrival timestamptz,\n  actual_departure timestamptz,\n  actual_arrival timestamptz,\n  cargo_description text,\n  cargo_weight_t numeric(7,2) check (cargo_weight_t >= 0),\n  recipient_name text,\n  recipient_phone text check (recipient_phone is null or recipient_phone ~ '^\\+[1-9][0-9]{7,14}$'),\n  client_reference text,\n  notes text,\n  cancel_reason text,\n  deleted_at timestamptz,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  check (planned_arrival is null or planned_departure is null or planned_arrival > planned_departure),\n  check (origin_place_id <> destination_place_id)\n);\ncreate unique index trips_one_active_vehicle on trips (vehicle_id) where status in ('em_viagem','pausada') and deleted_at is null;\ncreate unique index trips_one_active_driver on trips (driver_id) where status in ('em_viagem','pausada') and deleted_at is null;\ncreate index on trips (organization_id, status);\ncreate index on trips (organization_id, created_at desc);\ncreate trigger t_trip_upd before update on trips for each row execute function set_updated_at();\n\ncreate table trip_stops (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  seq int not null check (seq >= 1),\n  kind text not null default 'passagem' check (kind in ('entrega','recolha','passagem')),\n  place_id uuid not null references places(id),\n  recipient_name text,\n  recipient_phone text check (recipient_phone is null or recipient_phone ~ '^\\+[1-9][0-9]{7,14}$'),\n  planned_at timestamptz,\n  arrived_at timestamptz,\n  departed_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (trip_id, seq)\n);\ncreate trigger t_stop_upd before update on trip_stops for each row execute function set_updated_at();\n\ncreate table trip_events (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  kind text not null,\n  occurred_at timestamptz not null default now(),\n  actor_type text not null check (actor_type in ('member','driver','system')),\n  actor_id uuid,\n  payload jsonb not null default '{}'::jsonb,\n  position geography(Point, 4326),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on trip_events (trip_id, occurred_at);\n\ncreate table incidents (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  kind text not null check (kind in ('avaria','acidente','controlo_policial','estrada_cortada','outra')),\n  note text,\n  photo_file_id uuid references files(id) on delete set null,\n  occurred_at timestamptz not null default now(),\n  position geography(Point, 4326),\n  resolved_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table delivery_proofs (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  stop_id uuid references trip_stops(id) on delete set null,\n  received_by_name text not null check (length(received_by_name) >= 2),\n  signature_file_id uuid references files(id) on delete set null,\n  photo_file_id uuid references files(id) on delete set null,\n  delivered_at timestamptz not null default now(),\n  position geography(Point, 4326),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\n-- ── Máquina de estados (SPEC §6.6). Única forma de mudar o estado de uma viagem. ──\ncreate or replace function trip_transition(p_trip uuid, p_to trip_status, p_reason text default null)\nreturns trips language plpgsql security definer set search_path = public as $$\ndeclare t trips; actor_type text; actor uuid; allowed boolean := false; is_mgr boolean; is_drv boolean;\nbegin\n  select * into t from trips where id = p_trip and deleted_at is null for update;\n  if t.id is null then raise exception 'viagem_inexistente' using errcode = 'P0002'; end if;\n\n  is_mgr := app_user_id() is not null and can_write(t.organization_id);\n  is_drv := app_driver_id() is not null and t.driver_id = app_driver_id();\n  if not (is_mgr or is_drv) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  actor_type := case when is_mgr then 'member' else 'driver' end;\n  actor := coalesce(app_user_id(), app_driver_id());\n\n  allowed := case\n    when t.status = 'planeada' and p_to = 'aguardando_partida' then is_mgr\n    when t.status in ('planeada','aguardando_partida') and p_to = 'em_viagem' then is_mgr or is_drv\n    when t.status = 'em_viagem' and p_to = 'pausada' then true\n    when t.status = 'pausada' and p_to = 'em_viagem' then true\n    when t.status in ('em_viagem','pausada') and p_to = 'concluida' then true\n    when t.status in ('planeada','aguardando_partida','em_viagem','pausada') and p_to = 'cancelada' then is_mgr\n    else false end;\n  if not allowed then\n    raise exception 'transicao_invalida:%->%', t.status, p_to using errcode = 'P0001';\n  end if;\n  if p_to = 'em_viagem' and (t.vehicle_id is null or t.driver_id is null) then\n    raise exception 'viagem_sem_camiao_ou_motorista' using errcode = 'P0001';\n  end if;\n  if p_to = 'cancelada' and coalesce(length(trim(p_reason)), 0) < 3 then\n    raise exception 'motivo_obrigatorio' using errcode = 'P0001';\n  end if;\n\n  update trips set status = p_to,\n    actual_departure = case when p_to = 'em_viagem' and actual_departure is null then now() else actual_departure end,\n    actual_arrival = case when p_to = 'concluida' then now() else actual_arrival end,\n    cancel_reason = case when p_to = 'cancelada' then p_reason else cancel_reason end\n  where id = p_trip returning * into t;\n\n  insert into trip_events (organization_id, trip_id, kind, actor_type, actor_id, payload)\n  values (t.organization_id, t.id,\n    case p_to when 'em_viagem' then (case when t.actual_departure >= now() - interval '1 second' then 'partida' else 'retomada' end)\n              when 'pausada' then 'pausa' when 'concluida' then 'chegada' when 'cancelada' then 'cancelamento'\n              else 'estado' end,\n    actor_type, actor, jsonb_build_object('para', p_to, 'motivo', p_reason));\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id, after)\n  values (t.organization_id, actor_type, actor, 'viagem.estado', 'trips', t.id, jsonb_build_object('status', p_to));\n  return t;\nend $$;\n\n-- Impede mudar o estado por UPDATE direto (só via trip_transition, que corre como dono).\ncreate or replace function trips_guard_status() returns trigger language plpgsql as $$\nbegin\n  if new.status is distinct from old.status and current_user = 'app_api' then\n    raise exception 'use_trip_transition' using errcode = '42501';\n  end if;\n  return new;\nend $$;\ncreate trigger t_trip_guard before update on trips for each row execute function trips_guard_status();\n"],
  ["0004_percurso.sql", "-- 0004 — Geografia e percurso: datasets, áreas administrativas, cache de rotas, rotas da viagem,\n-- localidades da rota, progresso, estatísticas de velocidade, avisos por voz.\n-- Reversão: 0004_percurso.down.sql.\n\ncreate table geo_datasets (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  source_url text not null,\n  license text not null,\n  retrieved_at timestamptz not null,\n  version text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table admin_areas (\n  id uuid primary key default gen_random_uuid(),\n  level smallint not null check (level in (1, 2)),\n  name text not null,\n  code text not null,\n  parent_id uuid references admin_areas(id) on delete cascade,\n  geom geography(MultiPolygon, 4326) not null,\n  dataset_id uuid references geo_datasets(id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (level, code)\n);\ncreate index admin_areas_gix on admin_areas using gist (geom);\n\nalter table places add constraint places_province_fk foreign key (province_id) references admin_areas(id) on delete set null;\nalter table places add constraint places_district_fk foreign key (district_id) references admin_areas(id) on delete set null;\nalter table places add constraint places_dataset_fk foreign key (dataset_id) references geo_datasets(id) on delete set null;\n\ncreate table route_cache (\n  id uuid primary key default gen_random_uuid(),\n  cache_key text not null unique,\n  provider text not null,\n  profile jsonb not null,\n  geom geography(LineString, 4326) not null,\n  cum_m double precision[] not null,\n  length_m double precision not null check (length_m > 0),\n  duration_s double precision not null check (duration_s > 0),\n  roads text[] not null default '{}',\n  validated_for_truck boolean not null default false,\n  hits int not null default 0,\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table trip_routes (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  version int not null check (version >= 1),\n  reason text not null check (reason in ('plan','deviation','edit')),\n  provider text not null,\n  geom geography(LineString, 4326) not null,\n  cum_m double precision[] not null,\n  length_m double precision not null check (length_m > 0),\n  duration_s double precision not null check (duration_s > 0),\n  roads text[] not null default '{}',\n  validated_for_truck boolean not null default false,\n  is_current boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (trip_id, version)\n);\ncreate unique index trip_routes_current on trip_routes (trip_id) where is_current;\n\ncreate table trip_route_places (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_route_id uuid not null references trip_routes(id) on delete cascade,\n  place_id uuid not null references places(id),\n  seq int not null,\n  km_from_origin double precision not null check (km_from_origin >= 0),\n  offset_m double precision not null default 0, -- distância perpendicular da localidade à rota\n  state text not null default 'proxima' check (state in ('proxima','atual','passada')),\n  eta timestamptz,\n  eta_confidence text check (eta_confidence in ('alta','media','baixa','indisponivel')),\n  passed_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (trip_route_id, seq)\n);\ncreate trigger t_trp_upd before update on trip_route_places for each row execute function set_updated_at();\n\n-- Estado de progresso por viagem (uma linha), escrito pela ingestão. O motor é src/lib/geo/progress.ts.\ncreate table trip_progress (\n  trip_id uuid primary key references trips(id) on delete cascade,\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_route_id uuid references trip_routes(id) on delete set null,\n  km_done double precision,\n  km_left double precision,\n  pct double precision check (pct between 0 and 100),\n  current_label text,\n  current_place_id uuid references places(id),\n  next_place_id uuid references places(id),\n  province_id uuid references admin_areas(id),\n  eta_destination timestamptz,\n  eta_confidence text not null default 'indisponivel' check (eta_confidence in ('alta','media','baixa','indisponivel')),\n  speed_kmh_smoothed double precision,\n  last_position_at timestamptz,\n  engine_state jsonb not null default '{}'::jsonb, -- estado interno do motor (último ponto projetado, desvio, paragem)\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger t_tp_upd before update on trip_progress for each row execute function set_updated_at();\n\n-- Velocidades típicas por troço (aprendidas com viagens concluídas). Sem dados pessoais.\ncreate table segment_speed_stats (\n  id uuid primary key default gen_random_uuid(),\n  route_signature text not null,\n  segment_idx int not null,\n  p50_kmh double precision not null,\n  samples int not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (route_signature, segment_idx)\n);\n\ncreate table voice_announcements (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  idempotency_key text not null,\n  kind text not null,\n  text text not null,\n  triggered_at timestamptz not null,\n  km_at double precision,\n  played boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (trip_id, idempotency_key)\n);\n\n-- Lista de localidades ao longo de uma rota (horário de comboio), a partir da geometria.\n-- Só localidades públicas e privadas da organização, com importância mínima, a ≤ p_buffer_m da estrada.\ncreate or replace function places_along_route(p_geom geography, p_org uuid, p_min_importance int, p_buffer_m double precision)\nreturns table (place_id uuid, name text, kind text, importance smallint, province_id uuid, fraction double precision, offset_m double precision)\nlanguage sql stable security definer set search_path = public as $$\n  select p.id, p.name, p.kind, p.importance, p.province_id,\n         ST_LineLocatePoint(p_geom::geometry, p.geom::geometry) as fraction,\n         ST_Distance(p.geom, p_geom) as offset_m\n  from places p\n  where p.deleted_at is null\n    and (p.organization_id is null or p.organization_id = p_org)\n    and p.importance >= p_min_importance\n    and ST_DWithin(p.geom, p_geom, p_buffer_m)\n  order by fraction\n$$;\n\ncreate or replace function province_at(p_lng double precision, p_lat double precision)\nreturns table (id uuid, name text) language sql stable security definer set search_path = public as $$\n  select a.id, a.name from admin_areas a\n  where a.level = 1 and ST_Covers(a.geom, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography) limit 1\n$$;\n"],
  ["0005_telemetria.sql", "-- 0005 — Telemetria: posições (particionadas por mês), última posição, rejeições, percursos simplificados.\n-- Reversão: 0005_telemetria.down.sql.\n\ncreate table vehicle_positions (\n  id uuid not null default gen_random_uuid(),\n  organization_id uuid not null,\n  vehicle_id uuid not null,\n  trip_id uuid,\n  source text not null check (source in ('device','phone','simulator')),\n  source_id text not null,               -- 'device:<uuid>' | 'driver:<uuid>' | 'sim:<key uuid>'\n  device_time timestamptz not null,\n  sent_at timestamptz,\n  received_at timestamptz not null default now(),\n  geom geography(Point, 4326) not null,\n  speed_kmh real check (speed_kmh is null or speed_kmh >= 0),\n  heading real check (heading is null or (heading >= 0 and heading < 360)),\n  accuracy_m real check (accuracy_m is null or accuracy_m >= 0),\n  battery_pct smallint check (battery_pct is null or battery_pct between 0 and 100),\n  ignition boolean,\n  flags text[] not null default '{}',\n  primary key (id, device_time),\n  unique (source_id, device_time)\n) partition by range (device_time);\n\ncreate index on vehicle_positions (vehicle_id, device_time desc);\ncreate index on vehicle_positions (trip_id, device_time) where trip_id is not null;\ncreate index on vehicle_positions using brin (device_time);\n\n-- Cria partições mensais (passado próximo + futuro). Chamada pela migração e pelo job agendado.\ncreate or replace function ensure_position_partitions(p_months_back int default 1, p_months_ahead int default 2)\nreturns int language plpgsql security definer set search_path = public as $$\ndeclare m date; created int := 0; nm text;\nbegin\n  for i in -p_months_back..p_months_ahead loop\n    m := (date_trunc('month', now()) + make_interval(months => i))::date;\n    nm := 'vehicle_positions_' || to_char(m, 'YYYY_MM');\n    if to_regclass(nm) is null then\n      execute format('create table %I partition of vehicle_positions for values from (%L) to (%L)',\n        nm, m, (m + interval '1 month')::date);\n      execute format('alter table %I enable row level security', nm);\n      created := created + 1;\n    end if;\n  end loop;\n  return created;\nend $$;\nselect ensure_position_partitions(1, 2);\ncreate table vehicle_positions_default partition of vehicle_positions default;\n\ncreate table vehicle_latest_positions (\n  vehicle_id uuid primary key references vehicles(id) on delete cascade,\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid,\n  source text not null,\n  source_id text not null,\n  device_time timestamptz not null,\n  received_at timestamptz not null,\n  geom geography(Point, 4326) not null,\n  speed_kmh real,\n  heading real,\n  accuracy_m real,\n  battery_pct smallint,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on vehicle_latest_positions (organization_id);\n\ncreate table ingest_rejections (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid,\n  source_id text,\n  reason text not null,\n  payload jsonb,\n  received_at timestamptz not null default now(),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on ingest_rejections (organization_id, received_at desc);\n\ncreate table trip_tracks (\n  trip_id uuid primary key references trips(id) on delete cascade,\n  organization_id uuid not null references organizations(id) on delete cascade,\n  geom geography(LineString, 4326),\n  points_count int not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\n-- Ingestão (ADR-004/§6.8): grava o lote, sem duplicados, associa à viagem ativa no instante,\n-- atualiza a última posição só se for mais recente (e respeitando a prioridade da fonte, L9).\n-- Chamada SÓ pela API depois de autenticar a fonte e validar os pontos.\ncreate or replace function ingest_positions(p_org uuid, p_vehicle uuid, p_source text, p_source_id text, p_points jsonb)\nreturns table (id uuid, device_time timestamptz, trip_id uuid, lng double precision, lat double precision,\n               speed_kmh real, heading real, accuracy_m real, flags text[])\nlanguage plpgsql security definer set search_path = public as $$\n#variable_conflict use_column\ndeclare pt jsonb; dt timestamptz; t uuid; new_id uuid; prio text; cur vehicle_latest_positions; take boolean;\nbegin\n  if not exists (select 1 from vehicles v where v.id = p_vehicle and v.organization_id = p_org and v.deleted_at is null) then\n    raise exception 'veiculo_invalido' using errcode = '42501';\n  end if;\n  select gps_source_priority into prio from vehicles where vehicles.id = p_vehicle;\n\n  for pt in select * from jsonb_array_elements(p_points) order by (value->>'device_time')::timestamptz loop\n    dt := (pt->>'device_time')::timestamptz;\n    select tr.id into t from trips tr\n     where tr.vehicle_id = p_vehicle and tr.deleted_at is null and tr.status <> 'cancelada'\n       and tr.actual_departure is not null and tr.actual_departure <= dt\n       and (tr.actual_arrival is null or tr.actual_arrival >= dt)\n     order by tr.actual_departure desc limit 1;\n\n    insert into vehicle_positions (organization_id, vehicle_id, trip_id, source, source_id, device_time, sent_at,\n                                   geom, speed_kmh, heading, accuracy_m, battery_pct, ignition, flags)\n    values (p_org, p_vehicle, t, p_source, p_source_id, dt, (pt->>'sent_at')::timestamptz,\n            ST_SetSRID(ST_MakePoint((pt->>'lng')::float8, (pt->>'lat')::float8), 4326)::geography,\n            (pt->>'speed_kmh')::real, (pt->>'heading')::real, (pt->>'accuracy_m')::real,\n            (pt->>'battery_pct')::smallint, (pt->>'ignition')::boolean,\n            coalesce(array(select jsonb_array_elements_text(pt->'flags')), '{}'))\n    on conflict on constraint vehicle_positions_source_id_device_time_key do nothing\n    returning vehicle_positions.id into new_id;\n\n    if new_id is null then continue; end if; -- duplicado\n\n    select * into cur from vehicle_latest_positions where vehicle_latest_positions.vehicle_id = p_vehicle for update;\n    take := cur.vehicle_id is null\n         or (dt > cur.device_time and (\n               cur.source_id = p_source_id\n               or (case when p_source = 'device' then 'device' else 'phone' end) = prio\n               or cur.device_time < now() - interval '2 minutes'));\n    if take then\n      insert into vehicle_latest_positions (vehicle_id, organization_id, trip_id, source, source_id, device_time, received_at,\n                                            geom, speed_kmh, heading, accuracy_m, battery_pct)\n      values (p_vehicle, p_org, t, p_source, p_source_id, dt, now(),\n              ST_SetSRID(ST_MakePoint((pt->>'lng')::float8, (pt->>'lat')::float8), 4326)::geography,\n              (pt->>'speed_kmh')::real, (pt->>'heading')::real, (pt->>'accuracy_m')::real, (pt->>'battery_pct')::smallint)\n      on conflict (vehicle_id) do update set trip_id = excluded.trip_id, source = excluded.source, source_id = excluded.source_id,\n        device_time = excluded.device_time, received_at = excluded.received_at, geom = excluded.geom,\n        speed_kmh = excluded.speed_kmh, heading = excluded.heading, accuracy_m = excluded.accuracy_m,\n        battery_pct = excluded.battery_pct, updated_at = now();\n    end if;\n\n    return query select new_id, dt, t, (pt->>'lng')::float8, (pt->>'lat')::float8, (pt->>'speed_kmh')::real,\n      (pt->>'heading')::real, (pt->>'accuracy_m')::real, coalesce(array(select jsonb_array_elements_text(pt->'flags')), '{}');\n  end loop;\n\n  insert into usage_counters (organization_id, period, positions_ingested)\n    values (p_org, date_trunc('month', now())::date, jsonb_array_length(p_points))\n  on conflict (organization_id, period) do update set positions_ingested = usage_counters.positions_ingested + excluded.positions_ingested;\nend $$;\n\n-- Última posição anterior aceite (para rejeitar saltos impossíveis).\ncreate or replace function last_position_before(p_vehicle uuid, p_source_id text, p_time timestamptz)\nreturns table (device_time timestamptz, lng double precision, lat double precision)\nlanguage sql stable security definer set search_path = public as $$\n  select v.device_time, ST_X(v.geom::geometry), ST_Y(v.geom::geometry) from vehicle_positions v\n  where v.vehicle_id = p_vehicle and v.source_id = p_source_id and v.device_time < p_time\n    and v.device_time > p_time - interval '2 days'\n  order by v.device_time desc limit 1\n$$;\n\ncreate or replace function log_ingest_rejection(p_org uuid, p_source_id text, p_reason text, p_payload jsonb) returns void\nlanguage sql security definer set search_path = public as $$\n  insert into ingest_rejections (organization_id, source_id, reason, payload) values (p_org, p_source_id, p_reason, p_payload)\n$$;\n\n-- Percurso simplificado ao concluir (replay barato e permanente).\ncreate or replace function build_trip_track(p_trip uuid) returns void\nlanguage sql security definer set search_path = public as $$\n  insert into trip_tracks (trip_id, organization_id, geom, points_count)\n  select p_trip, max(organization_id::text)::uuid,\n         case when count(*) >= 2 then ST_SimplifyPreserveTopology(ST_MakeLine(geom::geometry order by device_time), 0.0001)::geography end,\n         count(*)\n  from vehicle_positions where trip_id = p_trip and not ('rejected' = any(flags))\n  having count(*) > 0\n  on conflict (trip_id) do update set geom = excluded.geom, points_count = excluded.points_count, updated_at = now()\n$$;\n\n-- Retenção por plano: apaga posições fora da retenção e partições antigas inteiras.\ncreate or replace function apply_position_retention() returns int\nlanguage plpgsql security definer set search_path = public as $$\ndeclare max_days int; r record; deleted int := 0; n int;\nbegin\n  select max((limits->>'retention_days')::int) into max_days from plans;\n  for r in select c.relname from pg_inherits i join pg_class c on c.oid = i.inhrelid\n           where i.inhparent = 'vehicle_positions'::regclass and c.relname ~ '^vehicle_positions_\\d{4}_\\d{2}$' loop\n    if to_date(substr(r.relname, 19), 'YYYY_MM') + interval '1 month' < now() - make_interval(days => max_days) then\n      execute format('drop table %I', r.relname);\n    end if;\n  end loop;\n  for r in select s.organization_id, (p.limits->>'retention_days')::int as days\n           from subscriptions s join plans p on p.id = s.plan_id where s.status <> 'canceled' loop\n    delete from vehicle_positions where organization_id = r.organization_id and device_time < now() - make_interval(days => r.days);\n    get diagnostics n = row_count; deleted := deleted + n;\n  end loop;\n  return deleted;\nend $$;\n"],
  ["0006_partilha.sql", "-- 0006 — Rastreamento público: partilhas, registo de acessos, limitação de taxa, DTO público (lista branca).\n-- Reversão: 0006_partilha.down.sql.\n\ncreate table tracking_shares (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  stop_id uuid references trip_stops(id) on delete cascade,\n  short_code text not null unique,      -- FT-XXXX-XXXX (para ditar)\n  token_hash text not null unique,      -- sha256 do token de 128 bits (o token nunca é guardado)\n  expires_at timestamptz not null,\n  revoked_at timestamptz,\n  is_active boolean not null default true,\n  options jsonb not null default '{\"show_company\":true,\"show_logo\":true,\"show_plate_masked\":false,\"show_driver_first_name\":false}'::jsonb,\n  views_count int not null default 0,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on tracking_shares (trip_id);\ncreate trigger t_ts_upd before update on tracking_shares for each row execute function set_updated_at();\n\ncreate table tracking_access_logs (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  share_id uuid not null references tracking_shares(id) on delete cascade,\n  accessed_at timestamptz not null default now(),\n  ip_hash text,\n  user_agent text,\n  via text not null check (via in ('code','link','preview')),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on tracking_access_logs (share_id, accessed_at desc);\n\n-- Janela fixa de limitação de taxa (usada pela API pública e pela ingestão).\ncreate table rate_limits (\n  bucket_key text not null,\n  window_start timestamptz not null,\n  count int not null default 0,\n  primary key (bucket_key, window_start)\n);\n\ncreate or replace function rate_limit_hit(p_key text, p_window_s int, p_max int) returns boolean\nlanguage plpgsql security definer set search_path = public as $$\ndeclare w timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_s) * p_window_s); c int;\nbegin\n  insert into rate_limits (bucket_key, window_start, count) values (p_key, w, 1)\n  on conflict (bucket_key, window_start) do update set count = rate_limits.count + 1\n  returning count into c;\n  return c <= p_max; -- true = permitido\nend $$;\n\n-- Matrícula parcialmente oculta: \"ADF 512 MP\" → \"ADF ••• MP\".\ncreate or replace function mask_plate(p text) returns text language sql immutable as $$\n  select case when p ~ '^\\S+\\s+\\S+\\s+\\S+$'\n    then split_part(p, ' ', 1) || ' ••• ' || split_part(p, ' ', 3)\n    else left(p, 2) || repeat('•', greatest(length(p) - 4, 1)) || right(p, 2) end\n$$;\n\n-- Resolve uma partilha por hash do token OU por código curto. Só devolve se ativa, válida e não revogada.\ncreate or replace function public_share_resolve(p_token_hash text, p_code text)\nreturns table (share_id uuid, trip_id uuid, organization_id uuid)\nlanguage sql stable security definer set search_path = public as $$\n  select s.id, s.trip_id, s.organization_id from tracking_shares s\n  where (s.token_hash = p_token_hash or (p_code is not null and s.short_code = upper(p_code)))\n    and s.is_active and s.revoked_at is null and s.expires_at > now()\n  limit 1\n$$;\n\ncreate or replace function public_share_log(p_share uuid, p_ip_hash text, p_ua text, p_via text) returns void\nlanguage sql security definer set search_path = public as $$\n  with s as (update tracking_shares set views_count = views_count + 1 where id = p_share returning organization_id)\n  insert into tracking_access_logs (organization_id, share_id, ip_hash, user_agent, via)\n  select organization_id, p_share, p_ip_hash, left(p_ua, 300), p_via from s\n$$;\n\n-- DTO PÚBLICO — lista branca de campos (SPEC §6.9). NUNCA: telefones, documentos, valores, IDs internos\n-- de veículo/motorista, dados de outros clientes, histórico fora da viagem. Após entrega/cancelamento: sem posição.\ncreate or replace function public_trip_dto(p_share uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare s tracking_shares; t trips; o organizations; v vehicles; d drivers; p trip_progress; lp vehicle_latest_positions;\n        r trip_routes; active boolean; result jsonb; places_json jsonb; done_geo jsonb; left_geo jsonb; frac double precision;\nbegin\n  select * into s from tracking_shares where id = p_share;\n  select * into t from trips where id = s.trip_id;\n  select * into o from organizations where id = t.organization_id;\n  select * into v from vehicles where id = t.vehicle_id;\n  select * into d from drivers where id = t.driver_id;\n  select * into p from trip_progress where trip_id = t.id;\n  select * into r from trip_routes where trip_id = t.id and is_current;\n  active := t.status in ('em_viagem','pausada');\n  if active and t.vehicle_id is not null then\n    select * into lp from vehicle_latest_positions where vehicle_id = t.vehicle_id and trip_id = t.id;\n  end if;\n\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'name', pl.name, 'km', round(rp.km_from_origin::numeric, 1), 'state', rp.state,\n      'passed_at', rp.passed_at, 'eta', case when active then rp.eta end,\n      'eta_confidence', case when active then rp.eta_confidence end) order by rp.seq), '[]'::jsonb)\n    into places_json\n  from trip_route_places rp join places pl on pl.id = rp.place_id\n  where rp.trip_route_id = r.id and pl.importance >= 3;\n\n  if r.id is not null and p.km_done is not null and r.length_m > 0 then\n    frac := least(greatest(p.km_done * 1000 / r.length_m, 0), 1);\n    done_geo := case when active and frac > 0 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, 0, frac), 0.0005), 5)::jsonb end;\n    left_geo := case when frac < 1 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, frac, 1), 0.0005), 5)::jsonb end;\n  elsif r.id is not null then\n    left_geo := ST_AsGeoJSON(ST_SimplifyPreserveTopology(r.geom::geometry, 0.0005), 5)::jsonb;\n  end if;\n\n  result := jsonb_build_object(\n    'code', t.code,\n    'status', t.status,\n    'origin', (select name from places where id = t.origin_place_id),\n    'destination', (select name from places where id = t.destination_place_id),\n    'origin_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.origin_place_id),\n    'destination_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.destination_place_id),\n    'departed_at', t.actual_departure,\n    'delivered_at', case when t.status = 'concluida' then t.actual_arrival end,\n    'planned_arrival', t.planned_arrival,\n    'position', case when active and lp.vehicle_id is not null then jsonb_build_object(\n        'lng', round(ST_X(lp.geom::geometry)::numeric, 5), 'lat', round(ST_Y(lp.geom::geometry)::numeric, 5),\n        'heading', lp.heading, 'device_time', lp.device_time) end,\n    'progress', case when active and p.km_done is not null then jsonb_build_object(\n        'pct', round(p.pct::numeric, 0), 'km_done', round(p.km_done::numeric, 0), 'km_left', round(p.km_left::numeric, 0),\n        'current_label', p.current_label,\n        'eta', case when p.eta_confidence <> 'indisponivel' then p.eta_destination end,\n        'eta_confidence', p.eta_confidence) end,\n    'route_done', done_geo,\n    'route_left', case when t.status in ('concluida','cancelada') then null else left_geo end,\n    'route_validated_for_truck', r.validated_for_truck,\n    'places', places_json,\n    'company', case when (s.options->>'show_company')::boolean then coalesce(o.public_name, o.name) end,\n    'logo_file_id', case when (s.options->>'show_logo')::boolean and o.logo_file_id is not null then s.id end,\n    'plate', case when (s.options->>'show_plate_masked')::boolean and v.id is not null then mask_plate(v.plate_normalized) end,\n    'driver_first_name', case when (s.options->>'show_driver_first_name')::boolean and d.id is not null then split_part(d.full_name, ' ', 1) end,\n    'server_time', now()\n  );\n  return result;\nend $$;\n\n-- Logótipo para a página pública (só se a partilha o permitir).\ncreate or replace function public_share_logo(p_share uuid) returns table (content_type text, data bytea)\nlanguage sql stable security definer set search_path = public as $$\n  select f.content_type, f.data from tracking_shares s join organizations o on o.id = s.organization_id\n  join files f on f.id = o.logo_file_id\n  where s.id = p_share and (s.options->>'show_logo')::boolean and s.revoked_at is null and s.expires_at > now()\n$$;\n"],
  ["0007_alertas.sql", "-- 0007 — Alertas e notificações: regras, alertas (aberto/reconhecido/resolvido), canais, push web, jobs.\n-- Reversão: 0007_alertas.down.sql.\n\ncreate table alert_rules (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  kind text not null check (kind in ('inicio_viagem','chegada','chegada_ponto','sem_sinal','atraso','desvio','paragem_anormal',\n                                      'manutencao_proxima','documento_expirar','dispositivo_problema')),\n  enabled boolean not null default true,\n  severity text not null default 'media' check (severity in ('baixa','media','alta')),\n  params jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, kind)\n);\ncreate trigger t_ar_upd before update on alert_rules for each row execute function set_updated_at();\n\ncreate table alerts (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  kind text not null,\n  severity text not null default 'media',\n  status text not null default 'aberto' check (status in ('aberto','reconhecido','resolvido')),\n  dedup_key text not null,\n  title text not null,\n  detail text,\n  vehicle_id uuid references vehicles(id) on delete cascade,\n  trip_id uuid references trips(id) on delete cascade,\n  driver_id uuid references drivers(id) on delete cascade,\n  document_id uuid references documents(id) on delete cascade,\n  payload jsonb not null default '{}'::jsonb,\n  opened_at timestamptz not null default now(),\n  acknowledged_by uuid,\n  acknowledged_at timestamptz,\n  resolved_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate unique index alerts_one_open on alerts (organization_id, dedup_key) where status <> 'resolvido';\ncreate index on alerts (organization_id, status, opened_at desc);\ncreate trigger t_al_upd before update on alerts for each row execute function set_updated_at();\n\ncreate table notification_channels (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  kind text not null check (kind in ('in_app','web_push','email','sms','whatsapp')),\n  enabled boolean not null default false,\n  config jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, kind)\n);\n\ncreate table push_subscriptions (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  user_id uuid not null references app_users(id) on delete cascade,\n  endpoint text not null unique,\n  keys jsonb not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table notifications (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  user_id uuid not null references app_users(id) on delete cascade,\n  alert_id uuid references alerts(id) on delete cascade,\n  channel text not null default 'in_app',\n  title text not null,\n  body text,\n  sent_at timestamptz,\n  read_at timestamptz,\n  error text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on notifications (user_id, read_at, created_at desc);\n\n-- Regras por omissão para cada organização nova.\ncreate or replace function seed_org_defaults() returns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  insert into alert_rules (organization_id, kind, severity, params) values\n    (new.id, 'inicio_viagem', 'baixa', '{}'), (new.id, 'chegada', 'baixa', '{}'), (new.id, 'chegada_ponto', 'baixa', '{}'),\n    (new.id, 'sem_sinal', 'alta', '{\"minutes\":15}'), (new.id, 'atraso', 'media', '{\"tolerance_min\":30}'),\n    (new.id, 'desvio', 'alta', '{\"corridor_m\":500,\"points\":3,\"min_minutes\":3,\"max_accuracy_m\":100}'),\n    (new.id, 'paragem_anormal', 'media', '{\"minutes\":30,\"radius_m\":150,\"max_speed_kmh\":3}'),\n    (new.id, 'manutencao_proxima', 'media', '{\"days\":7,\"km\":500}'),\n    (new.id, 'documento_expirar', 'media', '{\"days\":[30,15,7]}'),\n    (new.id, 'dispositivo_problema', 'media', '{\"hours\":24}')\n  on conflict do nothing;\n  insert into notification_channels (organization_id, kind, enabled) values\n    (new.id, 'in_app', true), (new.id, 'web_push', true), (new.id, 'email', false), (new.id, 'sms', false), (new.id, 'whatsapp', false)\n  on conflict do nothing;\n  return new;\nend $$;\ncreate trigger t_org_seed after insert on organizations for each row execute function seed_org_defaults();\n\n-- Abre um alerta se a regra estiver ativa e não houver um igual por resolver. Cria notificações na app.\ncreate or replace function open_alert(p_org uuid, p_kind text, p_dedup text, p_title text, p_detail text,\n  p_vehicle uuid default null, p_trip uuid default null, p_driver uuid default null, p_document uuid default null,\n  p_payload jsonb default '{}'::jsonb) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare rule alert_rules; a uuid;\nbegin\n  select * into rule from alert_rules where organization_id = p_org and kind = p_kind;\n  if rule.id is not null and not rule.enabled then return null; end if;\n  insert into alerts (organization_id, kind, severity, dedup_key, title, detail, vehicle_id, trip_id, driver_id, document_id, payload)\n  values (p_org, p_kind, coalesce(rule.severity, 'media'), p_dedup, p_title, p_detail, p_vehicle, p_trip, p_driver, p_document, p_payload)\n  on conflict (organization_id, dedup_key) where status <> 'resolvido' do nothing\n  returning id into a;\n  if a is not null then\n    insert into notifications (organization_id, user_id, alert_id, channel, title, body)\n    select p_org, m.user_id, a, 'in_app', p_title, p_detail from organization_members m\n    where m.organization_id = p_org and m.role in ('owner','admin','dispatcher');\n  end if;\n  return a;\nend $$;\n\ncreate or replace function resolve_alert_by_key(p_org uuid, p_dedup text) returns void\nlanguage sql security definer set search_path = public as $$\n  update alerts set status = 'resolvido', resolved_at = now()\n  where organization_id = p_org and dedup_key = p_dedup and status <> 'resolvido'\n$$;\n\n-- Job periódico (chamado pela Neon Function \"jobs\" via trigger de agenda, ADR-018).\ncreate or replace function run_periodic_jobs() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare r record; n_sinal int := 0; n_docs int := 0; n_manut int := 0; n_dev int := 0; mins int; d int;\nbegin\n  perform ensure_position_partitions(0, 2);\n\n  -- Sem sinal: viagem ativa cuja última posição tem mais de N minutos (um alerta por episódio).\n  for r in\n    select t.id trip_id, t.organization_id, t.vehicle_id, v.plate_normalized plate, lp.device_time,\n           coalesce((ar.params->>'minutes')::int, 15) lim\n    from trips t join vehicles v on v.id = t.vehicle_id\n    left join vehicle_latest_positions lp on lp.vehicle_id = t.vehicle_id\n    left join alert_rules ar on ar.organization_id = t.organization_id and ar.kind = 'sem_sinal'\n    where t.status = 'em_viagem' and t.deleted_at is null\n  loop\n    if r.device_time is null or r.device_time < now() - make_interval(mins => r.lim) then\n      if open_alert(r.organization_id, 'sem_sinal', 'sem_sinal:' || r.trip_id,\n           r.plate || ' sem comunicação GPS',\n           case when r.device_time is null then 'Ainda não houve nenhuma posição nesta viagem.'\n                else 'Última posição há ' || floor(extract(epoch from now() - r.device_time) / 60) || ' min.' end,\n           r.vehicle_id, r.trip_id) is not null then n_sinal := n_sinal + 1; end if;\n    else\n      perform resolve_alert_by_key(r.organization_id, 'sem_sinal:' || r.trip_id);\n    end if;\n  end loop;\n\n  -- Documentos a expirar (30/15/7 dias, configurável) e expirados.\n  for r in\n    select doc.*, coalesce(v.plate_normalized, dr.full_name) owner_label, ar.params\n    from documents doc left join vehicles v on v.id = doc.vehicle_id left join drivers dr on dr.id = doc.driver_id\n    left join alert_rules ar on ar.organization_id = doc.organization_id and ar.kind = 'documento_expirar'\n    where doc.expires_on is not null and doc.expires_on <= current_date + 30\n      and coalesce(v.deleted_at, dr.deleted_at) is null\n  loop\n    d := doc_days_left(r.expires_on);\n    if d < 0 or exists (select 1 from jsonb_array_elements_text(coalesce(r.params->'days', '[30,15,7]')) x where x::int >= d) then\n      if open_alert(r.organization_id, 'documento_expirar',\n           'doc:' || r.id || ':' || case when d < 0 then 'expirado' when d <= 7 then '7' when d <= 15 then '15' else '30' end,\n           case when d < 0 then 'Documento expirado: ' else 'Documento a expirar: ' end || r.owner_label,\n           replace(r.doc_type, '_', ' ') || coalesce(' n.º ' || r.number, '') || ' · validade ' || to_char(r.expires_on, 'DD/MM/YYYY'),\n           r.vehicle_id, null, r.driver_id, r.id) is not null then n_docs := n_docs + 1; end if;\n    end if;\n  end loop;\n\n  -- Manutenção próxima (por data ou por km).\n  for r in\n    select s.*, v.plate_normalized plate, v.odometer_km, ar.params from maintenance_schedules s\n    join vehicles v on v.id = s.vehicle_id and v.deleted_at is null\n    left join alert_rules ar on ar.organization_id = s.organization_id and ar.kind = 'manutencao_proxima'\n  loop\n    if (r.next_due_at is not null and r.next_due_at <= current_date + coalesce((r.params->>'days')::int, 7))\n       or (r.next_due_km is not null and r.odometer_km is not null and r.odometer_km >= r.next_due_km - coalesce((r.params->>'km')::int, 500)) then\n      if open_alert(r.organization_id, 'manutencao_proxima', 'manut:' || r.id || ':' || coalesce(r.next_due_at::text, '') || ':' || coalesce(r.next_due_km::text, ''),\n           'Manutenção próxima: ' || r.plate, r.kind, r.vehicle_id) is not null then n_manut := n_manut + 1; end if;\n    end if;\n  end loop;\n\n  -- Dispositivo sem contacto há mais de N horas.\n  for r in\n    select g.*, coalesce((ar.params->>'hours')::int, 24) lim from gps_devices g\n    left join alert_rules ar on ar.organization_id = g.organization_id and ar.kind = 'dispositivo_problema'\n    where g.deleted_at is null and g.status = 'ativo' and g.last_contact_at is not null\n  loop\n    if r.last_contact_at < now() - make_interval(hours => r.lim) then\n      if open_alert(r.organization_id, 'dispositivo_problema', 'dev:' || r.id, 'Dispositivo GPS sem contacto (IMEI ' || r.imei || ')',\n           'Último contacto: ' || to_char(r.last_contact_at at time zone 'Africa/Maputo', 'DD/MM HH24:MI')) is not null then n_dev := n_dev + 1; end if;\n    else\n      perform resolve_alert_by_key(r.organization_id, 'dev:' || r.id);\n    end if;\n  end loop;\n\n  delete from rate_limits where window_start < now() - interval '1 day';\n  delete from ingest_rejections where received_at < now() - interval '30 days';\n  delete from tracking_access_logs where accessed_at < now() - interval '90 days';\n  get diagnostics mins = row_count;\n\n  return jsonb_build_object('sem_sinal', n_sinal, 'documentos', n_docs, 'manutencao', n_manut, 'dispositivos', n_dev,\n                            'ran_at', now());\nend $$;\n\ncreate or replace function run_daily_jobs() returns jsonb language plpgsql security definer set search_path = public as $$\ndeclare n int;\nbegin\n  n := apply_position_retention();\n  return jsonb_build_object('positions_deleted', n, 'ran_at', now());\nend $$;\n\ncreate or replace function doc_days_left(p date) returns int language sql stable as\n$$ select (p - (now() at time zone 'Africa/Maputo')::date) $$;\n"],
  ["0008_custos.sql", "-- 0008 — Custos: combustível, manutenção (planos e registos), despesas de viagem.\n-- Reversão: 0008_custos.down.sql.\n\ncreate table fuel_records (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  vehicle_id uuid not null references vehicles(id) on delete cascade,\n  trip_id uuid references trips(id) on delete set null,\n  filled_at timestamptz not null,\n  liters numeric(9,2) not null check (liters > 0),\n  amount numeric(14,2) not null check (amount >= 0),\n  currency char(3) not null default 'MZN',\n  odometer_km numeric(10,1) check (odometer_km >= 0),\n  station text,\n  full_tank boolean not null default true,\n  receipt_file_id uuid references files(id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on fuel_records (vehicle_id, filled_at);\ncreate trigger t_fuel_upd before update on fuel_records for each row execute function set_updated_at();\n\ncreate table maintenance_schedules (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  vehicle_id uuid not null references vehicles(id) on delete cascade,\n  kind text not null,\n  every_km numeric(10,1) check (every_km > 0),\n  every_days int check (every_days > 0),\n  last_done_at date,\n  last_done_km numeric(10,1),\n  next_due_at date generated always as (last_done_at + every_days) stored,\n  next_due_km numeric(10,1) generated always as (last_done_km + every_km) stored,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  check (every_km is not null or every_days is not null)\n);\ncreate trigger t_ms_upd before update on maintenance_schedules for each row execute function set_updated_at();\n\ncreate table maintenance_records (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  vehicle_id uuid not null references vehicles(id) on delete cascade,\n  schedule_id uuid references maintenance_schedules(id) on delete set null,\n  kind text not null,\n  done_at date not null,\n  odometer_km numeric(10,1) check (odometer_km >= 0),\n  workshop text,\n  amount numeric(14,2) not null default 0 check (amount >= 0),\n  currency char(3) not null default 'MZN',\n  notes text,\n  receipt_file_id uuid references files(id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate trigger t_mr_upd before update on maintenance_records for each row execute function set_updated_at();\n\n-- Registar uma manutenção atualiza o plano associado.\ncreate or replace function maintenance_record_applied() returns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  if new.schedule_id is not null then\n    update maintenance_schedules set last_done_at = new.done_at, last_done_km = coalesce(new.odometer_km, last_done_km)\n    where id = new.schedule_id and organization_id = new.organization_id;\n  end if;\n  return new;\nend $$;\ncreate trigger t_mr_apply after insert on maintenance_records for each row execute function maintenance_record_applied();\n\ncreate table trip_expenses (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  category text not null check (category in ('portagem','alimentacao','alojamento','reparacao','outra')),\n  amount numeric(14,2) not null check (amount >= 0),\n  currency char(3) not null default 'MZN',\n  spent_at timestamptz not null default now(),\n  note text,\n  receipt_file_id uuid references files(id) on delete set null,\n  created_by_driver_id uuid references drivers(id) on delete set null,\n  created_by_user_id uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index on trip_expenses (trip_id);\ncreate trigger t_te_upd before update on trip_expenses for each row execute function set_updated_at();\n\n-- Consumo L/100 km entre abastecimentos de depósito cheio consecutivos (SPEC §6.13).\ncreate or replace view fuel_consumption_v with (security_invoker = true) as\nselect f.id, f.organization_id, f.vehicle_id, f.filled_at, f.liters, f.odometer_km,\n  prev.odometer_km as prev_odometer_km,\n  case when f.full_tank and prev.odometer_km is not null and f.odometer_km > prev.odometer_km\n       then round((f.liters * 100 / (f.odometer_km - prev.odometer_km))::numeric, 2) end as l_per_100km\nfrom fuel_records f\nleft join lateral (\n  select p.odometer_km from fuel_records p\n  where p.vehicle_id = f.vehicle_id and p.full_tank and p.filled_at < f.filled_at and p.odometer_km is not null\n  order by p.filled_at desc limit 1\n) prev on true;\n"],
  ["0009_rls.sql", "-- 0009 — Segurança: RLS em TODAS as tabelas do schema public, permissões do papel app_api,\n-- políticas por organização, políticas do motorista, vistas de estado.\n-- Reversão: 0009_rls.down.sql (remove políticas, vistas e permissões; desativa RLS).\n\n-- ── Ajudantes do contexto do motorista ──\ncreate or replace function app_driver_org() returns uuid language sql stable security definer set search_path = public as\n$$ select organization_id from drivers where id = app_driver_id() $$;\ncreate or replace function driver_owns_trip(p_trip uuid) returns boolean language sql stable security definer set search_path = public as\n$$ select app_driver_id() is not null and exists (select 1 from trips where id = p_trip and driver_id = app_driver_id() and deleted_at is null) $$;\ncreate or replace function can_see_costs(org uuid) returns boolean language sql stable as\n$$ select is_member(org, array['owner','admin','dispatcher']::org_role[]) $$;\n\n-- ── RLS em todas as tabelas (incluindo partições) ──\ndo $$ declare t record; begin\n  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace\n           where n.nspname = 'public' and c.relkind in ('r','p') and c.relname <> 'spatial_ref_sys' loop\n    execute format('alter table %I enable row level security', t.relname);\n  end loop;\nend $$;\n\n-- ── Permissões base do app_api ──\ngrant select, insert, update, delete on all tables in schema public to app_api;\nrevoke all on spatial_ref_sys from app_api;\ngrant select on spatial_ref_sys to app_api;\n-- Tabelas de autenticação/segredos: só através de funções SECURITY DEFINER.\nrevoke all on auth_sessions, password_resets, driver_sessions, rate_limits, ingest_rejections from app_api;\nrevoke all on driver_access from app_api;\ngrant select (id, organization_id, driver_id, failed_attempts, locked_until, last_used_at, revoked_at, created_at) on driver_access to app_api;\ngrant update (revoked_at) on driver_access to app_api;\nrevoke all on app_users from app_api;\ngrant select (id, email, full_name, phone, is_platform_admin, created_at) on app_users to app_api;\ngrant update (full_name, phone) on app_users to app_api;\nrevoke all on ingest_keys from app_api;\ngrant select (id, organization_id, name, scope, last_used_at, revoked_at, created_at) on ingest_keys to app_api;\ngrant update (revoked_at) on ingest_keys to app_api;\nrevoke insert, update, delete on vehicle_positions, vehicle_latest_positions, trip_tracks, usage_counters, plans, subscriptions,\n  support_grants, geo_datasets, admin_areas from app_api;\nrevoke update, delete on audit_logs from app_api;\ngrant usage on all sequences in schema public to app_api;\n\n-- Ajudante para criar políticas de forma uniforme.\ncreate or replace function _policy(tbl text, name text, cmd text, using_expr text, check_expr text default null) returns void\nlanguage plpgsql as $$\nbegin\n  execute format('drop policy if exists %I on %I', name, tbl);\n  execute format('create policy %I on %I for %s to app_api %s %s', name, tbl, cmd,\n    case when cmd = 'insert' or using_expr is null then '' else 'using (' || using_expr || ')' end,\n    case when check_expr is null then '' else 'with check (' || check_expr || ')' end);\nend $$;\n\n-- ── Contas e organizações ──\nselect _policy('app_users', 'sel', 'select',\n  'id = app_user_id() or exists (select 1 from organization_members a join organization_members b on a.organization_id = b.organization_id where a.user_id = app_user_id() and b.user_id = app_users.id) or is_platform_admin()');\nselect _policy('app_users', 'upd', 'update', 'id = app_user_id()', 'id = app_user_id()');\nselect _policy('organizations', 'sel', 'select', 'is_member(id) or id = app_driver_org() or is_platform_admin()');\nselect _policy('organizations', 'upd', 'update', 'can_admin(id)', 'can_admin(id)');\nselect _policy('organization_members', 'sel', 'select', 'is_member(organization_id) or is_platform_admin()');\nselect _policy('organization_members', 'ins', 'insert', null, 'can_admin(organization_id) and role <> ''owner''');\nselect _policy('organization_members', 'upd', 'update', 'can_admin(organization_id)', 'can_admin(organization_id) and (role <> ''owner'' or is_member(organization_id, array[''owner'']::org_role[]))');\nselect _policy('organization_members', 'del', 'delete', 'can_admin(organization_id)');\nselect _policy('organization_invites', 'sel', 'select', 'can_admin(organization_id)');\nselect _policy('organization_invites', 'ins', 'insert', null, 'can_admin(organization_id)');\nselect _policy('organization_invites', 'upd', 'update', 'can_admin(organization_id)', 'can_admin(organization_id)');\nselect _policy('organization_invites', 'del', 'delete', 'can_admin(organization_id)');\nselect _policy('plans', 'sel', 'select', 'true');\nselect _policy('subscriptions', 'sel', 'select', 'can_admin(organization_id) or is_platform_admin()');\nselect _policy('usage_counters', 'sel', 'select', 'can_admin(organization_id) or is_platform_admin()');\nselect _policy('support_grants', 'sel', 'select', 'can_admin(organization_id) or is_platform_admin()');\nselect _policy('audit_logs', 'sel', 'select', 'can_admin(organization_id) or is_platform_admin()');\nselect _policy('audit_logs', 'ins', 'insert', null,\n  '(actor_type = ''member'' and actor_id = app_user_id() and is_member(organization_id)) or (actor_type = ''driver'' and actor_id = app_driver_id() and organization_id = app_driver_org())');\n\n-- ── Tabelas privadas com padrão uniforme ──\n-- leitura: membros; escrita: owner/admin/dispatcher; eliminação: owner/admin.\ndo $$ declare t text; begin\n  foreach t in array array['vehicles','drivers','documents','trips','trip_stops','incidents','delivery_proofs',\n                           'trip_routes','trip_route_places','trip_progress','voice_announcements','trip_events','files',\n                           'tracking_shares','driver_consents'] loop\n    perform _policy(t, 'sel', 'select', 'is_member(organization_id)');\n    perform _policy(t, 'ins', 'insert', null, 'can_write(organization_id)');\n    perform _policy(t, 'upd', 'update', 'can_write(organization_id)', 'can_write(organization_id)');\n    perform _policy(t, 'del', 'delete', 'can_admin(organization_id)');\n  end loop;\n  -- dispositivos e chaves: só owner/admin escrevem\n  foreach t in array array['gps_devices','device_assignments','ingest_keys','alert_rules','notification_channels'] loop\n    perform _policy(t, 'sel', 'select', 'is_member(organization_id)');\n    perform _policy(t, 'ins', 'insert', null, 'can_admin(organization_id)');\n    perform _policy(t, 'upd', 'update', 'can_admin(organization_id)', 'can_admin(organization_id)');\n    perform _policy(t, 'del', 'delete', 'can_admin(organization_id)');\n  end loop;\n  -- custos: o perfil viewer não vê valores\n  foreach t in array array['fuel_records','maintenance_schedules','maintenance_records','trip_expenses'] loop\n    perform _policy(t, 'sel', 'select', 'can_see_costs(organization_id)');\n    perform _policy(t, 'ins', 'insert', null, 'can_write(organization_id)');\n    perform _policy(t, 'upd', 'update', 'can_write(organization_id)', 'can_write(organization_id)');\n    perform _policy(t, 'del', 'delete', 'can_admin(organization_id)');\n  end loop;\nend $$;\n-- driver_access: leitura por admins (sem colunas de hash), revogação por admins.\nselect _policy('driver_access', 'sel', 'select', 'can_admin(organization_id)');\nselect _policy('driver_access', 'upd', 'update', 'can_admin(organization_id)', 'can_admin(organization_id)');\nselect _policy('ingest_keys', 'sel', 'select', 'can_admin(organization_id)');\n\n-- Telemetria: só leitura (escrita só por ingest_positions).\nselect _policy('vehicle_positions', 'sel', 'select', 'is_member(organization_id)');\nselect _policy('vehicle_latest_positions', 'sel', 'select', 'is_member(organization_id)');\nselect _policy('trip_tracks', 'sel', 'select', 'is_member(organization_id)');\nselect _policy('tracking_access_logs', 'sel', 'select', 'can_write(organization_id)');\n\n-- Alertas e notificações\nselect _policy('alerts', 'sel', 'select', 'is_member(organization_id)');\nselect _policy('alerts', 'upd', 'update', 'can_write(organization_id)', 'can_write(organization_id)');\nselect _policy('notifications', 'sel', 'select', 'user_id = app_user_id()');\nselect _policy('notifications', 'upd', 'update', 'user_id = app_user_id()', 'user_id = app_user_id()');\nselect _policy('push_subscriptions', 'sel', 'select', 'user_id = app_user_id()');\nselect _policy('push_subscriptions', 'ins', 'insert', null, 'user_id = app_user_id() and is_member(organization_id)');\nselect _policy('push_subscriptions', 'del', 'delete', 'user_id = app_user_id()');\n\n-- Geografia: dados públicos de leitura; locais privados da organização.\nselect _policy('geo_datasets', 'sel', 'select', 'true');\nselect _policy('admin_areas', 'sel', 'select', 'true');\nselect _policy('places', 'sel', 'select', 'organization_id is null or is_member(organization_id) or organization_id = app_driver_org()');\nselect _policy('places', 'ins', 'insert', null, 'organization_id is not null and can_write(organization_id)');\nselect _policy('places', 'upd', 'update', 'organization_id is not null and can_write(organization_id)', 'organization_id is not null and can_write(organization_id)');\nselect _policy('places', 'del', 'delete', 'organization_id is not null and can_admin(organization_id)');\nselect _policy('route_cache', 'sel', 'select', 'true');\nselect _policy('route_cache', 'ins', 'insert', null, 'true');\nselect _policy('route_cache', 'upd', 'update', 'true', 'true');\nselect _policy('segment_speed_stats', 'sel', 'select', 'true');\nselect _policy('segment_speed_stats', 'ins', 'insert', null, 'true');\nselect _policy('segment_speed_stats', 'upd', 'update', 'true', 'true');\n\n-- ── Motorista (contexto app.driver_id): só as SUAS viagens ──\nselect _policy('trips', 'drv_sel', 'select', 'driver_id = app_driver_id()');\nselect _policy('drivers', 'drv_sel', 'select', 'id = app_driver_id()');\nselect _policy('vehicles', 'drv_sel', 'select', 'exists (select 1 from trips t where t.vehicle_id = vehicles.id and t.driver_id = app_driver_id())');\ndo $$ declare t text; begin\n  foreach t in array array['trip_stops','trip_routes','trip_progress','trip_events','incidents','delivery_proofs','voice_announcements','trip_expenses'] loop\n    perform _policy(t, 'drv_sel', 'select', 'driver_owns_trip(trip_id)');\n  end loop;\n  foreach t in array array['trip_events','incidents','delivery_proofs','voice_announcements','trip_expenses'] loop\n    perform _policy(t, 'drv_ins', 'insert', null, 'driver_owns_trip(trip_id) and organization_id = app_driver_org()');\n  end loop;\nend $$;\nselect _policy('trip_route_places', 'drv_sel', 'select',\n  'exists (select 1 from trip_routes r where r.id = trip_route_places.trip_route_id and driver_owns_trip(r.trip_id))');\nselect _policy('trip_stops', 'drv_upd', 'update', 'driver_owns_trip(trip_id)', 'driver_owns_trip(trip_id)');\nselect _policy('files', 'drv_ins', 'insert', null,\n  'organization_id = app_driver_org() and created_by = app_driver_id() and kind in (''receipt'',''delivery_photo'',''signature'',''incident_photo'')');\nselect _policy('files', 'drv_sel', 'select', 'organization_id = app_driver_org() and created_by = app_driver_id()');\nselect _policy('driver_consents', 'drv_ins', 'insert', null, 'driver_id = app_driver_id() and organization_id = app_driver_org()');\nselect _policy('driver_consents', 'drv_sel', 'select', 'driver_id = app_driver_id()');\n\n-- ── Viagens: só se criam no estado inicial; o estado muda só por trip_transition ──\ncreate or replace function trips_guard_status() returns trigger language plpgsql as $$\nbegin\n  if current_user = 'app_api' then\n    if tg_op = 'INSERT' and new.status <> 'planeada' then\n      raise exception 'use_trip_transition' using errcode = '42501';\n    elsif tg_op = 'UPDATE' and (new.status is distinct from old.status or new.actual_departure is distinct from old.actual_departure\n                                 or new.actual_arrival is distinct from old.actual_arrival) then\n      raise exception 'use_trip_transition' using errcode = '42501';\n    end if;\n  end if;\n  return new;\nend $$;\ndrop trigger if exists t_trip_guard on trips;\ncreate trigger t_trip_guard before insert or update on trips for each row execute function trips_guard_status();\n\n-- ── Estado derivado do veículo (SPEC §6.3) — uma só fonte de verdade ──\ncreate or replace view vehicle_status_v with (security_invoker = true) as\nselect v.id, v.organization_id, v.plate_normalized as plate, v.make, v.model, v.year, v.capacity_t, v.odometer_km, v.admin_status,\n  t.id as active_trip_id, t.code as active_trip_code, t.status as active_trip_status,\n  lp.device_time as last_position_at, lp.source as last_source, lp.speed_kmh, lp.heading,\n  ST_X(lp.geom::geometry) as lng, ST_Y(lp.geom::geometry) as lat,\n  exists (select 1 from device_assignments da where da.vehicle_id = v.id and da.valid_to is null) as has_device,\n  case\n    when lp.device_time is null then 'sem_dados'\n    when lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_current_s')::int, 120)) then 'atual'\n    when lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then 'desatualizada'\n    else 'sem_sinal' end as freshness,\n  case\n    when v.admin_status = 'em_manutencao' then 'em_manutencao'\n    when v.admin_status = 'inativo' then 'inativo'\n    when t.id is not null then 'em_viagem'\n    else 'disponivel' end as main_status\nfrom vehicles v\njoin organizations o on o.id = v.organization_id\nleft join trips t on t.vehicle_id = v.id and t.status in ('em_viagem','pausada') and t.deleted_at is null\nleft join vehicle_latest_positions lp on lp.vehicle_id = v.id\nwhere v.deleted_at is null;\ngrant select on vehicle_status_v, fuel_consumption_v to app_api;\n\n-- Futuras tabelas: permissões por omissão (mas RLS tem de ser ativado explicitamente; o teste falha se faltar).\nalter default privileges in schema public grant select, insert, update, delete on tables to app_api;\n"],
  ["0010_plataforma.sql", "-- 0010 — Funções privilegiadas controladas: emissão de acessos de motorista e chaves de ingestão,\n-- partilhas, administração da plataforma (planos, suporte auditado).\n-- Reversão: 0010_plataforma.down.sql.\n\ncreate or replace function driver_access_issue(p_driver uuid, p_token_hash text, p_pin_hash text) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare org uuid; a uuid;\nbegin\n  select organization_id into org from drivers where id = p_driver and deleted_at is null;\n  if org is null or not can_admin(org) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  update driver_access set revoked_at = now() where driver_id = p_driver and revoked_at is null;\n  update driver_sessions set revoked_at = now() where driver_id = p_driver and revoked_at is null;\n  insert into driver_access (organization_id, driver_id, token_hash, pin_hash, created_by)\n    values (org, p_driver, p_token_hash, p_pin_hash, app_user_id()) returning id into a;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (org, 'member', app_user_id(), 'motorista.acesso_emitido', 'drivers', p_driver);\n  return a;\nend $$;\n\ncreate or replace function driver_access_revoke(p_driver uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare org uuid;\nbegin\n  select organization_id into org from drivers where id = p_driver;\n  if org is null or not can_admin(org) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  update driver_access set revoked_at = now() where driver_id = p_driver and revoked_at is null;\n  update driver_sessions set revoked_at = now() where driver_id = p_driver and revoked_at is null;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (org, 'member', app_user_id(), 'motorista.acesso_revogado', 'drivers', p_driver);\nend $$;\n\ncreate or replace function ingest_key_issue(p_org uuid, p_name text, p_scope text, p_key_hash text) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare k uuid;\nbegin\n  if not can_admin(p_org) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  insert into ingest_keys (organization_id, name, scope, key_hash) values (p_org, p_name, p_scope, p_key_hash) returning id into k;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (p_org, 'member', app_user_id(), 'chave_ingestao.criar', 'ingest_keys', k);\n  return k;\nend $$;\n\n-- Partilhas: criar (limite do plano + auditoria), revogar.\ncreate or replace function share_create(p_trip uuid, p_stop uuid, p_token_hash text, p_expires timestamptz, p_options jsonb)\nreturns tracking_shares language plpgsql security definer set search_path = public as $$\ndeclare t trips; s tracking_shares; lim int; cnt int; code text; tries int := 0;\nbegin\n  select * into t from trips where id = p_trip and deleted_at is null;\n  if t.id is null or not can_write(t.organization_id) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  lim := plan_limit(t.organization_id, 'max_active_shares');\n  select count(*) into cnt from tracking_shares where organization_id = t.organization_id and is_active and revoked_at is null and expires_at > now();\n  if lim is not null and cnt >= lim then raise exception 'limite_plano:max_active_shares' using errcode = 'P0001'; end if;\n  loop\n    code := gen_ft_code(); tries := tries + 1;\n    exit when not exists (select 1 from tracking_shares where short_code = code) or tries > 5;\n  end loop;\n  insert into tracking_shares (organization_id, trip_id, stop_id, short_code, token_hash, expires_at, options, created_by)\n  values (t.organization_id, t.id, p_stop, code, p_token_hash, p_expires,\n          coalesce(p_options, '{\"show_company\":true,\"show_logo\":true,\"show_plate_masked\":false,\"show_driver_first_name\":false}'::jsonb), app_user_id())\n  returning * into s;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (t.organization_id, 'member', app_user_id(), 'partilha.criar', 'tracking_shares', s.id);\n  return s;\nend $$;\n\ncreate or replace function share_revoke(p_share uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare org uuid;\nbegin\n  select organization_id into org from tracking_shares where id = p_share;\n  if org is null or not can_write(org) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  update tracking_shares set revoked_at = now(), is_active = false where id = p_share;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (org, 'member', app_user_id(), 'partilha.revogar', 'tracking_shares', p_share);\nend $$;\n\n-- Plataforma (admin Insight)\ncreate or replace function platform_overview() returns table (\n  id uuid, name text, created_at timestamptz, plan_code text, sub_status text, members int, vehicles int, trips_30d int,\n  positions_month bigint, public_views_month bigint)\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if not is_platform_admin() then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  return query\n  select o.id, o.name, o.created_at, p.code, s.status,\n    (select count(*)::int from organization_members m where m.organization_id = o.id),\n    (select count(*)::int from vehicles v where v.organization_id = o.id and v.deleted_at is null),\n    (select count(*)::int from trips t where t.organization_id = o.id and t.created_at > now() - interval '30 days'),\n    coalesce(u.positions_ingested, 0), coalesce(u.public_views, 0)\n  from organizations o\n  left join subscriptions s on s.organization_id = o.id and s.status <> 'canceled'\n  left join plans p on p.id = s.plan_id\n  left join usage_counters u on u.organization_id = o.id and u.period = date_trunc('month', now())::date\n  where o.deleted_at is null order by o.created_at desc;\nend $$;\n\ncreate or replace function platform_set_plan(p_org uuid, p_plan_code text, p_status text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare pl uuid;\nbegin\n  if not is_platform_admin() then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  select id into pl from plans where code = p_plan_code;\n  if pl is null then raise exception 'plano_inexistente' using errcode = 'P0002'; end if;\n  update subscriptions set plan_id = pl, status = p_status where organization_id = p_org and status <> 'canceled';\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id, after)\n    values (p_org, 'platform', app_user_id(), 'plataforma.plano', 'subscriptions', p_org, jsonb_build_object('plan', p_plan_code, 'status', p_status));\nend $$;\n\ncreate or replace function platform_grant_support(p_org uuid, p_reason text, p_hours int) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare g uuid;\nbegin\n  if not is_platform_admin() then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  if p_hours < 1 or p_hours > 2 then raise exception 'duracao_invalida' using errcode = 'P0001'; end if;\n  insert into support_grants (organization_id, user_id, reason, expires_at)\n    values (p_org, app_user_id(), p_reason, now() + make_interval(hours => p_hours)) returning id into g;\n  -- Visível ao dono: fica na auditoria da organização e gera notificação.\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id, after)\n    values (p_org, 'platform', app_user_id(), 'plataforma.acesso_suporte', 'support_grants', g, jsonb_build_object('motivo', p_reason, 'horas', p_hours));\n  insert into notifications (organization_id, user_id, channel, title, body)\n    select p_org, m.user_id, 'in_app', 'Acesso de suporte concedido', 'A equipa insightFrota tem acesso de leitura por ' || p_hours || ' h. Motivo: ' || p_reason\n    from organization_members m where m.organization_id = p_org and m.role = 'owner';\n  return g;\nend $$;\n"],
  ["0011_rota_base.sql", "-- 0011 — Recálculo após desvio: a nova rota começa na posição atual; base_km guarda os km já feitos\n-- para que o progresso total continue correto. Reversão: alter table trip_routes drop column base_km.\nalter table trip_routes add column base_km double precision not null default 0 check (base_km >= 0);\n"],
  ["0012_utilizacao_e_eta.sql", "-- 0012 — Contadores de utilização por função controlada; ETA público só com posição recente.\n-- Reversão: drop function bump_usage; repor public_trip_dto de 0006.\n\ncreate or replace function bump_usage(p_org uuid, p_field text, p_n int default 1) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if p_field not in ('positions_ingested','route_requests','public_views') then raise exception 'campo_invalido'; end if;\n  execute format('insert into usage_counters (organization_id, period, %1$I) values ($1, date_trunc(''month'', now())::date, $2)\n    on conflict (organization_id, period) do update set %1$I = usage_counters.%1$I + excluded.%1$I', p_field) using p_org, p_n;\nend $$;\n\n-- Versão revista do DTO público (igual à de 0006, com ETA dependente da frescura da posição).\ncreate or replace function public_trip_dto(p_share uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare s tracking_shares; t trips; o organizations; v vehicles; d drivers; p trip_progress; lp vehicle_latest_positions;\n        r trip_routes; active boolean; result jsonb; places_json jsonb; done_geo jsonb; left_geo jsonb; frac double precision;\nbegin\n  select * into s from tracking_shares where id = p_share;\n  select * into t from trips where id = s.trip_id;\n  select * into o from organizations where id = t.organization_id;\n  select * into v from vehicles where id = t.vehicle_id;\n  select * into d from drivers where id = t.driver_id;\n  select * into p from trip_progress where trip_id = t.id;\n  select * into r from trip_routes where trip_id = t.id and is_current;\n  active := t.status in ('em_viagem','pausada');\n  if active and t.vehicle_id is not null then\n    select * into lp from vehicle_latest_positions where vehicle_id = t.vehicle_id and trip_id = t.id;\n  end if;\n\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'name', pl.name, 'km', round(rp.km_from_origin::numeric, 1), 'state', rp.state,\n      'passed_at', rp.passed_at, 'eta', case when active then rp.eta end,\n      'eta_confidence', case when active then rp.eta_confidence end) order by rp.seq), '[]'::jsonb)\n    into places_json\n  from trip_route_places rp join places pl on pl.id = rp.place_id\n  where rp.trip_route_id = r.id and pl.importance >= 3;\n\n  if r.id is not null and p.km_done is not null and r.length_m > 0 then\n    frac := least(greatest(p.km_done * 1000 / r.length_m, 0), 1);\n    done_geo := case when active and frac > 0 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, 0, frac), 0.0005), 5)::jsonb end;\n    left_geo := case when frac < 1 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, frac, 1), 0.0005), 5)::jsonb end;\n  elsif r.id is not null then\n    left_geo := ST_AsGeoJSON(ST_SimplifyPreserveTopology(r.geom::geometry, 0.0005), 5)::jsonb;\n  end if;\n\n  result := jsonb_build_object(\n    'code', s.short_code,\n    'status', t.status,\n    'origin', (select name from places where id = t.origin_place_id),\n    'destination', (select name from places where id = t.destination_place_id),\n    'origin_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.origin_place_id),\n    'destination_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.destination_place_id),\n    'departed_at', t.actual_departure,\n    'delivered_at', case when t.status = 'concluida' then t.actual_arrival end,\n    'planned_arrival', t.planned_arrival,\n    'position', case when active and lp.vehicle_id is not null then jsonb_build_object(\n        'lng', round(ST_X(lp.geom::geometry)::numeric, 5), 'lat', round(ST_Y(lp.geom::geometry)::numeric, 5),\n        'heading', lp.heading, 'device_time', lp.device_time) end,\n    'progress', case when active and p.km_done is not null then jsonb_build_object(\n        'pct', round(p.pct::numeric, 0), 'km_done', round(p.km_done::numeric, 0), 'km_left', round(p.km_left::numeric, 0),\n        'current_label', p.current_label,\n        'eta', case when p.eta_confidence <> 'indisponivel' and lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then p.eta_destination end,\n        'eta_confidence', case when lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then p.eta_confidence else 'indisponivel' end) end,\n    'route_done', done_geo,\n    'route_left', case when t.status in ('concluida','cancelada') then null else left_geo end,\n    'route_validated_for_truck', r.validated_for_truck,\n    'places', places_json,\n    'company', case when (s.options->>'show_company')::boolean then coalesce(o.public_name, o.name) end,\n    'logo_file_id', case when (s.options->>'show_logo')::boolean and o.logo_file_id is not null then s.id end,\n    'plate', case when (s.options->>'show_plate_masked')::boolean and v.id is not null then mask_plate(v.plate_normalized) end,\n    'driver_first_name', case when (s.options->>'show_driver_first_name')::boolean and d.id is not null then split_part(d.full_name, ' ', 1) end,\n    'server_time', now()\n  );\n  return result;\nend $$;\n\n\n-- Partilha: a primeira usa o código da viagem; o DTO público mostra o código da partilha.\ncreate or replace function share_create(p_trip uuid, p_stop uuid, p_token_hash text, p_expires timestamptz, p_options jsonb)\nreturns tracking_shares language plpgsql security definer set search_path = public as $$\ndeclare t trips; s tracking_shares; lim int; cnt int; code text; tries int := 0;\nbegin\n  select * into t from trips where id = p_trip and deleted_at is null;\n  if t.id is null or not can_write(t.organization_id) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  lim := plan_limit(t.organization_id, 'max_active_shares');\n  select count(*) into cnt from tracking_shares where organization_id = t.organization_id and is_active and revoked_at is null and expires_at > now();\n  if lim is not null and cnt >= lim then raise exception 'limite_plano:max_active_shares' using errcode = 'P0001'; end if;\n  -- 1.ª partilha usa o próprio código da viagem (o que o dono vê e dita); ao regenerar, código novo.\n  if not exists (select 1 from tracking_shares where short_code = t.code) then code := t.code; else\n  loop\n    code := gen_ft_code(); tries := tries + 1;\n    exit when not exists (select 1 from tracking_shares where short_code = code) and not exists (select 1 from trips where trips.code = code) or tries > 5;\n  end loop;\n  end if;\n  insert into tracking_shares (organization_id, trip_id, stop_id, short_code, token_hash, expires_at, options, created_by)\n  values (t.organization_id, t.id, p_stop, code, p_token_hash, p_expires,\n          coalesce(p_options, '{\"show_company\":true,\"show_logo\":true,\"show_plate_masked\":false,\"show_driver_first_name\":false}'::jsonb), app_user_id())\n  returning * into s;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id)\n    values (t.organization_id, 'member', app_user_id(), 'partilha.criar', 'tracking_shares', s.id);\n  return s;\nend $$;\n\n"],
  ["0013_transicao_offline.sql", "-- 0013 — Transições com a hora real da ação (fila offline do motorista, lacuna L3/RNF-7).\n-- Reversão: drop function trip_transition(uuid, trip_status, text, timestamptz) e repor a versão de 0003.\ndrop function if exists trip_transition(uuid, trip_status, text);\ncreate or replace function trip_transition(p_trip uuid, p_to trip_status, p_reason text default null, p_at timestamptz default null)\nreturns trips language plpgsql security definer set search_path = public as $$\ndeclare t trips; actor_type text; actor uuid; allowed boolean := false; is_mgr boolean; is_drv boolean; at_ts timestamptz;\nbegin\n  select * into t from trips where id = p_trip and deleted_at is null for update;\n  if t.id is null then raise exception 'viagem_inexistente' using errcode = 'P0002'; end if;\n\n  is_mgr := app_user_id() is not null and can_write(t.organization_id);\n  is_drv := app_driver_id() is not null and t.driver_id = app_driver_id();\n  if not (is_mgr or is_drv) then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  actor_type := case when is_mgr then 'member' else 'driver' end;\n  actor := coalesce(app_user_id(), app_driver_id());\n\n  allowed := case\n    when t.status = 'planeada' and p_to = 'aguardando_partida' then is_mgr\n    when t.status in ('planeada','aguardando_partida') and p_to = 'em_viagem' then is_mgr or is_drv\n    when t.status = 'em_viagem' and p_to = 'pausada' then true\n    when t.status = 'pausada' and p_to = 'em_viagem' then true\n    when t.status in ('em_viagem','pausada') and p_to = 'concluida' then true\n    when t.status in ('planeada','aguardando_partida','em_viagem','pausada') and p_to = 'cancelada' then is_mgr\n    else false end;\n  if not allowed then\n    raise exception 'transicao_invalida:%->%', t.status, p_to using errcode = 'P0001';\n  end if;\n  if p_to = 'em_viagem' and (t.vehicle_id is null or t.driver_id is null) then\n    raise exception 'viagem_sem_camiao_ou_motorista' using errcode = 'P0001';\n  end if;\n  if p_to = 'cancelada' and coalesce(length(trim(p_reason)), 0) < 3 then\n    raise exception 'motivo_obrigatorio' using errcode = 'P0001';\n  end if;\n\n  -- Hora real da ação (fila offline do motorista): nunca no futuro, no máximo 24 h atrás, nunca antes da criação.\n  at_ts := least(now(), greatest(coalesce(p_at, now()), now() - interval '24 hours', t.created_at));\n  if p_to = 'concluida' and t.actual_departure is not null then at_ts := greatest(at_ts, t.actual_departure); end if;\n  update trips set status = p_to,\n    actual_departure = case when p_to = 'em_viagem' and actual_departure is null then at_ts else actual_departure end,\n    actual_arrival = case when p_to = 'concluida' then at_ts else actual_arrival end,\n    cancel_reason = case when p_to = 'cancelada' then p_reason else cancel_reason end\n  where id = p_trip returning * into t;\n\n  insert into trip_events (organization_id, trip_id, kind, actor_type, actor_id, payload, occurred_at)\n  values (t.organization_id, t.id,\n    case p_to when 'em_viagem' then (case when t.actual_departure = at_ts then 'partida' else 'retomada' end)\n              when 'pausada' then 'pausa' when 'concluida' then 'chegada' when 'cancelada' then 'cancelamento'\n              else 'estado' end,\n    actor_type, actor, jsonb_build_object('para', p_to, 'motivo', p_reason), at_ts);\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id, after)\n  values (t.organization_id, actor_type, actor, 'viagem.estado', 'trips', t.id, jsonb_build_object('status', p_to));\n  return t;\nend $$;\n\n"],
  ["0014_ingestao_tolerancia_partida.sql", "-- 0014 — A 1.ª posição do telemóvel pode ter hora ligeiramente anterior ao \"Iniciar viagem\"\n-- (o navegador entrega a última posição em cache). Tolerância de 2 min na associação à viagem.\n-- Reversão: repor a função de 0005_telemetria.sql.\ncreate or replace function ingest_positions(p_org uuid, p_vehicle uuid, p_source text, p_source_id text, p_points jsonb)\nreturns table (id uuid, device_time timestamptz, trip_id uuid, lng double precision, lat double precision,\n               speed_kmh real, heading real, accuracy_m real, flags text[])\nlanguage plpgsql security definer set search_path = public as $$\n#variable_conflict use_column\ndeclare pt jsonb; dt timestamptz; t uuid; new_id uuid; prio text; cur vehicle_latest_positions; take boolean;\nbegin\n  if not exists (select 1 from vehicles v where v.id = p_vehicle and v.organization_id = p_org and v.deleted_at is null) then\n    raise exception 'veiculo_invalido' using errcode = '42501';\n  end if;\n  select gps_source_priority into prio from vehicles where vehicles.id = p_vehicle;\n\n  for pt in select * from jsonb_array_elements(p_points) order by (value->>'device_time')::timestamptz loop\n    dt := (pt->>'device_time')::timestamptz;\n    select tr.id into t from trips tr\n     where tr.vehicle_id = p_vehicle and tr.deleted_at is null and tr.status <> 'cancelada'\n       and tr.actual_departure is not null and tr.actual_departure - interval '2 minutes' <= dt\n       and (tr.actual_arrival is null or tr.actual_arrival >= dt)\n     order by tr.actual_departure desc limit 1;\n\n    insert into vehicle_positions (organization_id, vehicle_id, trip_id, source, source_id, device_time, sent_at,\n                                   geom, speed_kmh, heading, accuracy_m, battery_pct, ignition, flags)\n    values (p_org, p_vehicle, t, p_source, p_source_id, dt, (pt->>'sent_at')::timestamptz,\n            ST_SetSRID(ST_MakePoint((pt->>'lng')::float8, (pt->>'lat')::float8), 4326)::geography,\n            (pt->>'speed_kmh')::real, (pt->>'heading')::real, (pt->>'accuracy_m')::real,\n            (pt->>'battery_pct')::smallint, (pt->>'ignition')::boolean,\n            coalesce(array(select jsonb_array_elements_text(pt->'flags')), '{}'))\n    on conflict on constraint vehicle_positions_source_id_device_time_key do nothing\n    returning vehicle_positions.id into new_id;\n\n    if new_id is null then continue; end if; -- duplicado\n\n    select * into cur from vehicle_latest_positions where vehicle_latest_positions.vehicle_id = p_vehicle for update;\n    take := cur.vehicle_id is null\n         or (dt > cur.device_time and (\n               cur.source_id = p_source_id\n               or (case when p_source = 'device' then 'device' else 'phone' end) = prio\n               or cur.device_time < now() - interval '2 minutes'));\n    if take then\n      insert into vehicle_latest_positions (vehicle_id, organization_id, trip_id, source, source_id, device_time, received_at,\n                                            geom, speed_kmh, heading, accuracy_m, battery_pct)\n      values (p_vehicle, p_org, t, p_source, p_source_id, dt, now(),\n              ST_SetSRID(ST_MakePoint((pt->>'lng')::float8, (pt->>'lat')::float8), 4326)::geography,\n              (pt->>'speed_kmh')::real, (pt->>'heading')::real, (pt->>'accuracy_m')::real, (pt->>'battery_pct')::smallint)\n      on conflict (vehicle_id) do update set trip_id = excluded.trip_id, source = excluded.source, source_id = excluded.source_id,\n        device_time = excluded.device_time, received_at = excluded.received_at, geom = excluded.geom,\n        speed_kmh = excluded.speed_kmh, heading = excluded.heading, accuracy_m = excluded.accuracy_m,\n        battery_pct = excluded.battery_pct, updated_at = now();\n    end if;\n\n    return query select new_id, dt, t, (pt->>'lng')::float8, (pt->>'lat')::float8, (pt->>'speed_kmh')::real,\n      (pt->>'heading')::real, (pt->>'accuracy_m')::real, coalesce(array(select jsonb_array_elements_text(pt->'flags')), '{}');\n  end loop;\n\n  insert into usage_counters (organization_id, period, positions_ingested)\n    values (p_org, date_trunc('month', now())::date, jsonb_array_length(p_points))\n  on conflict (organization_id, period) do update set positions_ingested = usage_counters.positions_ingested + excluded.positions_ingested;\nend $$;\n\n"],
  ["0015_estrada_e_teste_real.sql", "-- 0015 — Dados reais da estrada (ajuste à estrada, nome, limite de velocidade do OSM) e teste com o telemóvel do utilizador.\n-- Reversão: remover as colunas acrescentadas (alter table ... drop column ...).\n\n-- Última posição: posição ajustada à estrada (map matching do Valhalla) + estrada + limite (só se etiquetado no OSM).\nalter table vehicle_latest_positions\n  add column matched_geom geography(Point, 4326),\n  add column road_name text,\n  add column speed_limit_kmh smallint check (speed_limit_kmh is null or speed_limit_kmh between 5 and 200),\n  add column matched_at timestamptz;\n\nalter table trip_progress\n  add column road_name text,\n  add column speed_limit_kmh smallint check (speed_limit_kmh is null or speed_limit_kmh between 5 and 200);\n\n-- Motorista ligado a um membro (o dono a testar com o próprio telemóvel). Nulo para motoristas normais.\nalter table drivers add column user_id uuid references app_users(id) on delete set null;\ncreate unique index drivers_user_uq on drivers (organization_id, user_id) where user_id is not null and deleted_at is null;\nalter table vehicles add column is_test boolean not null default false;\n\n\n-- Página pública: o camião aparece em cima da estrada quando há ajuste da última posição; senão, posição GPS bruta.\n-- Mesmos campos da lista branca. Reversão: repor a função de 0012.\ncreate or replace function public_trip_dto(p_share uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare s tracking_shares; t trips; o organizations; v vehicles; d drivers; p trip_progress; lp vehicle_latest_positions;\n        r trip_routes; active boolean; result jsonb; places_json jsonb; done_geo jsonb; left_geo jsonb; frac double precision;\nbegin\n  select * into s from tracking_shares where id = p_share;\n  select * into t from trips where id = s.trip_id;\n  select * into o from organizations where id = t.organization_id;\n  select * into v from vehicles where id = t.vehicle_id;\n  select * into d from drivers where id = t.driver_id;\n  select * into p from trip_progress where trip_id = t.id;\n  select * into r from trip_routes where trip_id = t.id and is_current;\n  active := t.status in ('em_viagem','pausada');\n  if active and t.vehicle_id is not null then\n    select * into lp from vehicle_latest_positions where vehicle_id = t.vehicle_id and trip_id = t.id;\n  end if;\n\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'name', pl.name, 'km', round(rp.km_from_origin::numeric, 1), 'state', rp.state,\n      'passed_at', rp.passed_at, 'eta', case when active then rp.eta end,\n      'eta_confidence', case when active then rp.eta_confidence end) order by rp.seq), '[]'::jsonb)\n    into places_json\n  from trip_route_places rp join places pl on pl.id = rp.place_id\n  where rp.trip_route_id = r.id and pl.importance >= 3;\n\n  if r.id is not null and p.km_done is not null and r.length_m > 0 then\n    frac := least(greatest(p.km_done * 1000 / r.length_m, 0), 1);\n    done_geo := case when active and frac > 0 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, 0, frac), 0.0005), 5)::jsonb end;\n    left_geo := case when frac < 1 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, frac, 1), 0.0005), 5)::jsonb end;\n  elsif r.id is not null then\n    left_geo := ST_AsGeoJSON(ST_SimplifyPreserveTopology(r.geom::geometry, 0.0005), 5)::jsonb;\n  end if;\n\n  result := jsonb_build_object(\n    'code', s.short_code,\n    'status', t.status,\n    'origin', (select name from places where id = t.origin_place_id),\n    'destination', (select name from places where id = t.destination_place_id),\n    'origin_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.origin_place_id),\n    'destination_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.destination_place_id),\n    'departed_at', t.actual_departure,\n    'delivered_at', case when t.status = 'concluida' then t.actual_arrival end,\n    'planned_arrival', t.planned_arrival,\n    'position', case when active and lp.vehicle_id is not null then jsonb_build_object(\n        'lng', round(ST_X((case when lp.matched_geom is not null and lp.matched_at >= lp.device_time - interval '1 second' then lp.matched_geom else lp.geom end)::geometry)::numeric, 5),\n        'lat', round(ST_Y((case when lp.matched_geom is not null and lp.matched_at >= lp.device_time - interval '1 second' then lp.matched_geom else lp.geom end)::geometry)::numeric, 5),\n        'heading', lp.heading, 'device_time', lp.device_time) end,\n    'progress', case when active and p.km_done is not null then jsonb_build_object(\n        'pct', round(p.pct::numeric, 0), 'km_done', round(p.km_done::numeric, 0), 'km_left', round(p.km_left::numeric, 0),\n        'current_label', p.current_label,\n        'eta', case when p.eta_confidence <> 'indisponivel' and lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then p.eta_destination end,\n        'eta_confidence', case when lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then p.eta_confidence else 'indisponivel' end) end,\n    'route_done', done_geo,\n    'route_left', case when t.status in ('concluida','cancelada') then null else left_geo end,\n    'route_validated_for_truck', r.validated_for_truck,\n    'places', places_json,\n    'company', case when (s.options->>'show_company')::boolean then coalesce(o.public_name, o.name) end,\n    'logo_file_id', case when (s.options->>'show_logo')::boolean and o.logo_file_id is not null then s.id end,\n    'plate', case when (s.options->>'show_plate_masked')::boolean and v.id is not null then mask_plate(v.plate_normalized) end,\n    'driver_first_name', case when (s.options->>'show_driver_first_name')::boolean and d.id is not null then split_part(d.full_name, ' ', 1) end,\n    'server_time', now()\n  );\n  return result;\nend $$;\n\n-- O camião de teste (o telemóvel do dono) não conta para o limite do plano; no máximo 1 por organização.\n-- Reversão: repor enforce_plan_limit de 0002 e apagar o índice.\ncreate unique index vehicles_test_uq on vehicles (organization_id) where is_test and deleted_at is null;\ncreate or replace function enforce_plan_limit() returns trigger language plpgsql security definer set search_path = public as $$\ndeclare lim int; cnt int; key text := tg_argv[0];\nbegin\n  if tg_table_name = 'vehicles' then\n    if (to_jsonb(new)->>'is_test')::boolean then return new; end if;\n  end if;\n  lim := plan_limit(new.organization_id, key);\n  if lim is null then return new; end if;\n  execute format('select count(*) from %I where organization_id = $1 and %s', tg_table_name,\n    case tg_table_name when 'vehicles' then 'deleted_at is null and not is_test' when 'gps_devices' then 'deleted_at is null' else 'true' end)\n    into cnt using new.organization_id;\n  if cnt >= lim then\n    raise exception 'limite_plano:%', key using errcode = 'P0001';\n  end if;\n  return new;\nend $$;\n"],
  ["0016_teste_um_toque.sql", "-- 0016 — \"Testar com o meu telemóvel\" com um toque: o motorista ligado ao próprio utilizador (o dono a testar)\n-- não precisa de número de telefone. Motoristas normais continuam a exigir telefone.\n-- Reversão: preencher os telefones em falta e repor \"alter table drivers alter column phone set not null\".\nalter table drivers alter column phone drop not null;\nalter table drivers add constraint drivers_phone_required check (phone is not null or user_id is not null);\n"],
  ["0017_motorista_bi.sql", "-- 0017 — Número do BI do motorista (Bilhete de Identidade de Moçambique: 12 algarismos + 1 letra).\n-- Opcional na BD (motoristas antigos e \"Eu próprio\" continuam válidos); o formulário exige-o nos novos.\n-- Único por organização (a mesma pessoa pode trabalhar para duas empresas diferentes).\n-- A tabela drivers já tem RLS por organização: a coluna nova fica coberta pelas mesmas políticas.\n-- Reversão: drop index if exists drivers_id_number_uq; alter table drivers drop column if exists id_number;\nalter table drivers add column if not exists id_number text\n  check (id_number is null or id_number ~ '^[0-9]{12}[A-Z]$');\ncreate unique index if not exists drivers_id_number_uq on drivers (organization_id, id_number)\n  where id_number is not null and deleted_at is null;\n"],
  ["0018_distritos_publico.sql", "-- 0018 — Distritos visíveis ao cliente: lista dos distritos atravessados pela rota e o distrito da última posição real,\n-- na lista branca do DTO público (sem geometria, sem dados privados). A função route_districts é a mesma lógica usada\n-- pela app do motorista (server/trip-route.ts): amostra a rota a cada 400 m e regista as mudanças de distrito (ADM2).\n-- Reversão: repor public_trip_dto de 0015_estrada_e_teste_real.sql e \"drop function route_districts(uuid)\".\ncreate or replace function route_districts(p_route uuid)\nreturns table (code text, name text, province text, km double precision)\nlanguage sql stable set search_path = public as $$\n  with r as (select geom::geometry g, length_m, base_km from trip_routes where id = p_route),\n  pts as (select ST_LineLocatePoint(r.g, d.geom) f, d.geom p from r, ST_DumpPoints(ST_Segmentize(r.g::geography, 400)::geometry) d),\n  lab as (select f, (select a.id from admin_areas a where a.level = 2 and ST_Covers(a.geom, p::geography) order by ST_Area(a.geom) limit 1) aid from pts),\n  runs as (select f, aid, lag(aid) over (order by f) prev from lab where aid is not null),\n  -- entradas; passagens de menos de 1 km por um distrito (ex.: a estrada a tocar num limite) não contam\n  ent as (select f, aid, lead(f) over (order by f) nf from runs where aid is distinct from prev),\n  firm as (select f, aid from ent where nf is null or (nf - f) * (select length_m from r) >= 1000),\n  fin as (select f, aid, lag(aid) over (order by f) prev from firm)\n  select a.code, a.name, pv.name, ((select base_km from r) + fin.f * (select length_m from r) / 1000)::float8\n  from fin join admin_areas a on a.id = fin.aid left join admin_areas pv on pv.id = a.parent_id\n  where fin.aid is distinct from fin.prev order by fin.f\n$$;\n\ncreate or replace function public_trip_dto(p_share uuid) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare s tracking_shares; t trips; o organizations; v vehicles; d drivers; p trip_progress; lp vehicle_latest_positions;\n        r trip_routes; active boolean; result jsonb; places_json jsonb; done_geo jsonb; left_geo jsonb; frac double precision;\n        dist_json jsonb; cur_district jsonb;\nbegin\n  select * into s from tracking_shares where id = p_share;\n  select * into t from trips where id = s.trip_id;\n  select * into o from organizations where id = t.organization_id;\n  select * into v from vehicles where id = t.vehicle_id;\n  select * into d from drivers where id = t.driver_id;\n  select * into p from trip_progress where trip_id = t.id;\n  select * into r from trip_routes where trip_id = t.id and is_current;\n  active := t.status in ('em_viagem','pausada');\n  if active and t.vehicle_id is not null then\n    select * into lp from vehicle_latest_positions where vehicle_id = t.vehicle_id and trip_id = t.id;\n  end if;\n\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'name', pl.name, 'km', round(rp.km_from_origin::numeric, 1), 'state', rp.state,\n      'passed_at', rp.passed_at, 'eta', case when active then rp.eta end,\n      'eta_confidence', case when active then rp.eta_confidence end) order by rp.seq), '[]'::jsonb)\n    into places_json\n  from trip_route_places rp join places pl on pl.id = rp.place_id\n  where rp.trip_route_id = r.id and pl.importance >= 3;\n\n  -- distritos atravessados pela rota (nome, província, km desde a origem) e o distrito da última posição real\n  select coalesce(jsonb_agg(jsonb_build_object('name', rd.name, 'province', rd.province, 'km', round(rd.km::numeric, 1)) order by rd.km), '[]'::jsonb)\n    into dist_json from route_districts(r.id) rd where r.id is not null;\n  if active and lp.vehicle_id is not null then\n    select jsonb_build_object('name', a.name, 'province', pv.name) into cur_district\n    from admin_areas a left join admin_areas pv on pv.id = a.parent_id\n    where a.level = 2 and ST_Covers(a.geom, coalesce(lp.matched_geom, lp.geom))\n    order by ST_Area(a.geom) limit 1;\n  end if;\n\n  if r.id is not null and p.km_done is not null and r.length_m > 0 then\n    frac := least(greatest(p.km_done * 1000 / r.length_m, 0), 1);\n    done_geo := case when active and frac > 0 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, 0, frac), 0.0005), 5)::jsonb end;\n    left_geo := case when frac < 1 then ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_LineSubstring(r.geom::geometry, frac, 1), 0.0005), 5)::jsonb end;\n  elsif r.id is not null then\n    left_geo := ST_AsGeoJSON(ST_SimplifyPreserveTopology(r.geom::geometry, 0.0005), 5)::jsonb;\n  end if;\n\n  result := jsonb_build_object(\n    'code', s.short_code,\n    'status', t.status,\n    'origin', (select name from places where id = t.origin_place_id),\n    'destination', (select name from places where id = t.destination_place_id),\n    'origin_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.origin_place_id),\n    'destination_point', (select jsonb_build_array(round(ST_X(geom::geometry)::numeric, 5), round(ST_Y(geom::geometry)::numeric, 5)) from places where id = t.destination_place_id),\n    'departed_at', t.actual_departure,\n    'delivered_at', case when t.status = 'concluida' then t.actual_arrival end,\n    'planned_arrival', t.planned_arrival,\n    'position', case when active and lp.vehicle_id is not null then jsonb_build_object(\n        'lng', round(ST_X((case when lp.matched_geom is not null and lp.matched_at >= lp.device_time - interval '1 second' then lp.matched_geom else lp.geom end)::geometry)::numeric, 5),\n        'lat', round(ST_Y((case when lp.matched_geom is not null and lp.matched_at >= lp.device_time - interval '1 second' then lp.matched_geom else lp.geom end)::geometry)::numeric, 5),\n        'heading', lp.heading, 'device_time', lp.device_time) end,\n    'progress', case when active and p.km_done is not null then jsonb_build_object(\n        'pct', round(p.pct::numeric, 0), 'km_done', round(p.km_done::numeric, 0), 'km_left', round(p.km_left::numeric, 0),\n        'current_label', p.current_label,\n        'eta', case when p.eta_confidence <> 'indisponivel' and lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then p.eta_destination end,\n        'eta_confidence', case when lp.device_time > now() - make_interval(secs => coalesce((o.settings->>'freshness_stale_s')::int, 900)) then p.eta_confidence else 'indisponivel' end) end,\n    'route_done', done_geo,\n    'route_left', case when t.status in ('concluida','cancelada') then null else left_geo end,\n    'route_validated_for_truck', r.validated_for_truck,\n    'places', places_json,\n    'districts', coalesce(dist_json, '[]'::jsonb),\n    'district', cur_district,\n    'company', case when (s.options->>'show_company')::boolean then coalesce(o.public_name, o.name) end,\n    'logo_file_id', case when (s.options->>'show_logo')::boolean and o.logo_file_id is not null then s.id end,\n    'plate', case when (s.options->>'show_plate_masked')::boolean and v.id is not null then mask_plate(v.plate_normalized) end,\n    'driver_first_name', case when (s.options->>'show_driver_first_name')::boolean and d.id is not null then split_part(d.full_name, ' ', 1) end,\n    'server_time', now()\n  );\n  return result;\nend $$;\n"],
  ["0019_distritos_no_mapa.sql", "-- 0019 — Distritos no mapa: limites (simplificados, ~1 km) e ponto para o nome de cada distrito atravessado pela rota.\n-- Dados geográficos públicos (geoBoundaries ADM2, CC BY 4.0); nada da organização além da rota já partilhada.\n-- Reversão: drop function route_areas(uuid).\ncreate or replace function route_areas(p_route uuid) returns jsonb\nlanguage sql stable set search_path = public as $$\n  select coalesce(jsonb_agg(jsonb_build_object(\n      'name', a.name, 'province', pv.name,\n      'boundary', ST_AsGeoJSON(ST_SimplifyPreserveTopology(ST_Boundary(a.geom::geometry), 0.01), 3)::jsonb,\n      'label', jsonb_build_array(round(ST_X(ST_PointOnSurface(a.geom::geometry))::numeric, 4), round(ST_Y(ST_PointOnSurface(a.geom::geometry))::numeric, 4)))\n    order by a.name), '[]'::jsonb)\n  from admin_areas a left join admin_areas pv on pv.id = a.parent_id\n  where a.level = 2 and a.code in (select code from route_districts(p_route))\n$$;\n"],
  ["0020_pagamentos.sql", "-- 0020 — Pagamento por viagem: a 1.ª viagem real de cada organização é grátis; as seguintes pagam (250 MT por omissão)\n-- por M-Pesa / e-Mola. O cliente envia o código da transação e a fotografia do comprovativo (lida no telemóvel).\n-- Confirmação: automática quando o mesmo código (ou o número de quem pagou + o valor) chega num SMS reencaminhado do telemóvel do proprietário\n-- (o SMS só existe se o dinheiro entrou), senão manual pela plataforma. Uma fotografia sozinha NUNCA aprova.\n-- O bloqueio está na BD (gatilho em trips): não se inicia uma viagem por fora do checkout.\n-- Reversão: drop trigger trips_payment_gate on trips; drop function trip_can_start(trips), trips_payment_gate(),\n--   payment_decide(uuid, boolean, text), payment_match_sms(uuid), payment_autostart(uuid); drop table payment_sms, trip_payments, billing_settings;\n--   alter table organizations drop column payments_blocked.\n\ncreate table billing_settings (\n  id boolean primary key default true check (id),          -- uma só linha\n  price_per_trip numeric(14,2) not null default 250 check (price_per_trip >= 0),\n  currency char(3) not null default 'MZN',\n  free_trips int not null default 1 check (free_trips >= 0),\n  mpesa_number text, mpesa_name text,\n  emola_number text, emola_name text,\n  updated_at timestamptz not null default now()\n);\ninsert into billing_settings default values;\n\nalter table organizations add column payments_blocked boolean not null default false;\n\ncreate table trip_payments (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references organizations(id) on delete cascade,\n  trip_id uuid not null references trips(id) on delete cascade,\n  amount numeric(14,2) not null check (amount > 0),\n  currency char(3) not null default 'MZN',\n  method text not null check (method in ('mpesa','emola')),\n  transaction_id text not null check (transaction_id ~ '^[A-Z0-9]{6,20}$'),\n  payer_phone text,\n  receipt_file_id uuid references files(id) on delete set null,\n  ocr_text text, ocr_amount numeric(14,2), ocr_recipient text, ocr_date text,\n  status text not null default 'pendente' check (status in ('pendente','aprovado','rejeitado')),\n  auto boolean not null default false,\n  sms_id uuid,\n  decided_by uuid, decided_at timestamptz, reason text,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n-- cada código de transação só serve UMA vez em todo o sistema (exceto se foi rejeitado)\ncreate unique index trip_payments_tx_uq on trip_payments (transaction_id) where status <> 'rejeitado';\ncreate index on trip_payments (organization_id, created_at desc);\ncreate index on trip_payments (trip_id);\n\n-- SMS de pagamento reencaminhados do telemóvel do proprietário (só a plataforma vê)\ncreate table payment_sms (\n  id uuid primary key default gen_random_uuid(),\n  raw text not null,\n  sender text,\n  transaction_id text,\n  amount numeric(14,2),\n  payer text,\n  method text,\n  received_at timestamptz not null default now(),\n  matched_payment_id uuid references trip_payments(id) on delete set null\n);\ncreate unique index payment_sms_tx_uq on payment_sms (transaction_id) where transaction_id is not null;\n\nalter table billing_settings enable row level security;\nalter table trip_payments enable row level security;\nalter table payment_sms enable row level security;\n-- preço e números: todos os membros autenticados leem (o checkout mostra-os); só a plataforma altera (via função)\nselect _policy('billing_settings', 'sel', 'select', 'app_user_id() is not null');\nselect _policy('trip_payments', 'sel', 'select', 'can_write(organization_id) or is_platform_admin()');\nselect _policy('trip_payments', 'ins', 'insert', null, 'can_write(organization_id) and status = ''pendente'' and not auto');\nselect _policy('payment_sms', 'sel', 'select', 'is_platform_admin()');\nrevoke update, delete on trip_payments from app_api;\nrevoke insert, update, delete on billing_settings, payment_sms from app_api;\n\n/** A viagem pode começar? Teste do telemóvel, viagens grátis restantes ou pagamento aprovado para esta viagem. */\ncreate or replace function trip_can_start(t trips) returns boolean\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare b billing_settings; used int; blocked boolean;\nbegin\n  if exists (select 1 from vehicles v where v.id = t.vehicle_id and v.is_test) then return true; end if;\n  -- a empresa do próprio dono da plataforma não paga a si mesma\n  if exists (select 1 from organization_members om join app_users u on u.id = om.user_id where om.organization_id = t.organization_id and u.is_platform_admin) then return true; end if;\n  if exists (select 1 from trip_payments p where p.trip_id = t.id and p.status = 'aprovado') then return true; end if;\n  select * into b from billing_settings limit 1;\n  select payments_blocked into blocked from organizations where id = t.organization_id;\n  -- viagens reais já iniciadas (mesmo apagadas: apagar não devolve a viagem grátis)\n  select count(*) into used from trips x left join vehicles v on v.id = x.vehicle_id\n   where x.organization_id = t.organization_id and x.id <> t.id and x.actual_departure is not null and not coalesce(v.is_test, false);\n  return not coalesce(blocked, false) and used < coalesce(b.free_trips, 1);\nend $$;\n\ncreate or replace function trips_payment_gate() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if new.status = 'em_viagem' and new.actual_departure is not null\n     and (tg_op = 'INSERT' or old.actual_departure is null) and not trip_can_start(new) then\n    raise exception 'pagamento_necessario' using errcode = 'P0001';\n  end if;\n  return new;\nend $$;\ncreate trigger trips_payment_gate before insert or update of status, actual_departure on trips\n  for each row execute function trips_payment_gate();\n\n/** Pagamento aprovado → a viagem começa sozinha (se ainda estiver por iniciar e tiver camião e motorista).\n * Se o camião/motorista estiver noutra viagem em curso, fica por iniciar (o cliente inicia quando quiser). */\ncreate or replace function payment_autostart(p_trip uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare t trips;\nbegin\n  select * into t from trips where id = p_trip and deleted_at is null for update;\n  if t.id is null or t.status not in ('planeada','aguardando_partida') or t.vehicle_id is null or t.driver_id is null then return; end if;\n  begin\n    update trips set status = 'em_viagem', actual_departure = coalesce(actual_departure, now()) where id = t.id;\n    insert into trip_events (organization_id, trip_id, kind, actor_type, payload)\n    values (t.organization_id, t.id, 'partida', 'system', jsonb_build_object('para', 'em_viagem', 'motivo', 'pagamento confirmado'));\n  exception when unique_violation then null; -- camião/motorista ocupado: fica por iniciar\n  end;\nend $$;\n\n/** Aprovar/rejeitar (plataforma). 3 rejeições bloqueiam a organização até a plataforma desbloquear. */\ncreate or replace function payment_decide(p_id uuid, p_approve boolean, p_reason text) returns trip_payments\nlanguage plpgsql security definer set search_path = public as $$\ndeclare p trip_payments;\nbegin\n  if not is_platform_admin() then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  update trip_payments set status = case when p_approve then 'aprovado' else 'rejeitado' end, decided_by = app_user_id(),\n    decided_at = now(), reason = p_reason, updated_at = now()\n  where id = p_id and status = 'pendente' returning * into p;\n  if p.id is null then raise exception 'pagamento_inexistente' using errcode = 'P0002'; end if;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id, after)\n  values (p.organization_id, 'platform', app_user_id(), case when p_approve then 'pagamento.aprovar' else 'pagamento.rejeitar' end,\n    'trip_payments', p.id, jsonb_build_object('motivo', p_reason, 'valor', p.amount, 'codigo', p.transaction_id));\n  if not p_approve and (select count(*) from trip_payments where organization_id = p.organization_id and status = 'rejeitado') >= 3 then\n    update organizations set payments_blocked = true where id = p.organization_id;\n  end if;\n  if p_approve then perform payment_autostart(p.trip_id); end if;\n  return p;\nend $$;\n\n/** Liga um pagamento pendente a um SMS recebido com o MESMO código e valor suficiente → aprovado sozinho. */\ncreate or replace function payment_match_sms(p_id uuid) returns boolean\nlanguage plpgsql security definer set search_path = public as $$\ndeclare p trip_payments; s payment_sms;\nbegin\n  select * into p from trip_payments where id = p_id and status = 'pendente' for update;\n  if p.id is null then return false; end if;\n  -- 1) o MESMO código da transação; 2) senão, o número de quem pagou + o valor, num SMS das últimas 24 h\n  select * into s from payment_sms where transaction_id = p.transaction_id and matched_payment_id is null\n    and amount >= p.amount and received_at > now() - interval '7 days' limit 1;\n  if s.id is null and p.payer_phone is not null then\n    select * into s from payment_sms where payer = p.payer_phone and matched_payment_id is null\n      and amount >= p.amount and received_at > now() - interval '24 hours' order by received_at desc limit 1;\n  end if;\n  if s.id is null then return false; end if;\n  update trip_payments set status = 'aprovado', auto = true, sms_id = s.id, decided_at = now(), updated_at = now() where id = p.id;\n  update payment_sms set matched_payment_id = p.id where id = s.id;\n  insert into audit_logs (organization_id, actor_type, action, entity, entity_id, after)\n  values (p.organization_id, 'system', 'pagamento.aprovar_sms', 'trip_payments', p.id, jsonb_build_object('codigo', p.transaction_id, 'valor', s.amount));\n  perform payment_autostart(p.trip_id);\n  return true;\nend $$;\n"],
  ["0021_pagamento_ia.sql", "-- 0021 — Pagamento sem SMS: o comprovativo é analisado por IA (visão) + verificações duras no servidor (ADR-030).\n-- Aprovado sozinho só se tudo bater certo e a IA não vir sinais de edição; dúvidas → \"em análise\" (o proprietário decide);\n-- o proprietário pode ANULAR um pagamento aprovado (era burla): a viagem é cancelada e a empresa fica bloqueada.\n-- Reversão: drop function payment_ai_decide(uuid, text, text, jsonb, int), payment_revoke(uuid, text);\n--   drop index trip_payments_img_uq; alter table trip_payments drop column ai_result, drop column ai_risk, drop column image_sha256,\n--   drop column image_dhash, drop column decided_by_ai; repor o check de status sem 'anulado' (depois de mudar os 'anulado' para 'rejeitado').\n\nalter table trip_payments drop constraint if exists trip_payments_status_check;\nalter table trip_payments add constraint trip_payments_status_check check (status in ('pendente','aprovado','rejeitado','anulado'));\nalter table trip_payments add column ai_result jsonb, add column ai_risk int, add column image_sha256 text, add column image_dhash text,\n  add column decided_by_ai boolean not null default false;\n-- a mesma imagem (byte a byte) só serve para UM pagamento em todo o sistema\ncreate unique index trip_payments_img_uq on trip_payments (image_sha256) where image_sha256 is not null and status <> 'rejeitado';\n\n/** Decisão do sistema depois da análise (só o servidor, ligação de sistema). Aprovado → a viagem começa sozinha.\n *  5 rejeições em 24 h bloqueiam a empresa (alguém a tentar comprovativos falsos). */\ncreate or replace function payment_ai_decide(p_id uuid, p_status text, p_reason text, p_ai jsonb, p_risk int) returns trip_payments\nlanguage plpgsql security definer set search_path = public as $$\ndeclare p trip_payments;\nbegin\n  if p_status not in ('pendente','aprovado','rejeitado') then raise exception 'estado_invalido' using errcode = 'P0001'; end if;\n  update trip_payments set status = p_status, reason = p_reason, ai_result = p_ai, ai_risk = p_risk,\n    decided_by_ai = (p_status <> 'pendente'), auto = (p_status = 'aprovado'),\n    decided_at = case when p_status <> 'pendente' then now() end, updated_at = now()\n  where id = p_id and status = 'pendente' returning * into p;\n  if p.id is null then raise exception 'pagamento_inexistente' using errcode = 'P0002'; end if;\n  if p_status <> 'pendente' then\n    insert into audit_logs (organization_id, actor_type, action, entity, entity_id, after)\n    values (p.organization_id, 'system', case p_status when 'aprovado' then 'pagamento.aprovar_ia' else 'pagamento.rejeitar_ia' end,\n      'trip_payments', p.id, jsonb_build_object('codigo', p.transaction_id, 'risco', p_risk, 'motivo', p_reason));\n  end if;\n  if p_status = 'rejeitado' and (select count(*) from trip_payments where organization_id = p.organization_id\n      and status = 'rejeitado' and created_at > now() - interval '24 hours') >= 5 then\n    update organizations set payments_blocked = true where id = p.organization_id;\n  end if;\n  if p_status = 'aprovado' then perform payment_autostart(p.trip_id); end if;\n  return p;\nend $$;\nrevoke all on function payment_ai_decide(uuid, text, text, jsonb, int) from public;\n\n/** \"Era burla\" (plataforma): anula um pagamento aprovado, cancela a viagem (o cliente deixa de a seguir) e bloqueia a empresa. */\ncreate or replace function payment_revoke(p_id uuid, p_reason text) returns trip_payments\nlanguage plpgsql security definer set search_path = public as $$\ndeclare p trip_payments; t trips;\nbegin\n  if not is_platform_admin() then raise exception 'sem_permissao' using errcode = '42501'; end if;\n  if coalesce(length(trim(p_reason)), 0) < 3 then raise exception 'motivo_obrigatorio' using errcode = 'P0001'; end if;\n  update trip_payments set status = 'anulado', reason = p_reason, decided_by = app_user_id(), decided_at = now(), updated_at = now()\n  where id = p_id and status = 'aprovado' returning * into p;\n  if p.id is null then raise exception 'pagamento_inexistente' using errcode = 'P0002'; end if;\n  update organizations set payments_blocked = true where id = p.organization_id;\n  select * into t from trips where id = p.trip_id and deleted_at is null for update;\n  if t.id is not null and t.status not in ('concluida','cancelada') then\n    update trips set status = 'cancelada', cancel_reason = 'Pagamento anulado: ' || p_reason where id = t.id;\n    insert into trip_events (organization_id, trip_id, kind, actor_type, payload)\n    values (t.organization_id, t.id, 'cancelamento', 'system', jsonb_build_object('para', 'cancelada', 'motivo', 'pagamento anulado'));\n  end if;\n  insert into audit_logs (organization_id, actor_type, actor_id, action, entity, entity_id, after)\n  values (p.organization_id, 'platform', app_user_id(), 'pagamento.anular', 'trip_payments', p.id,\n    jsonb_build_object('motivo', p_reason, 'codigo', p.transaction_id, 'valor', p.amount));\n  return p;\nend $$;\n"],
];
